  (1112, 111, 'modal-verbs-2', 'modal 2nd, infinitive at the end', 'word_order', '{1041}'::int[], 10, 19),
  (1121, 112, 'separable-verbs-1', 'anrufen → Ich rufe dich an.', 'word_order', '{1041}'::int[], 10, 20),
  (1122, 112, 'separable-verbs-2', 'which form? (kommt … an, but: anrufen with a modal)', 'verb_form', '{}'::int[], 10, 21),
  (1131, 113, 'possessives-1', 'mein, dein, sein, ihr, unser, euer, Ihr', 'pronoun', '{}'::int[], 10, 22),
  (1132, 113, 'possessives-2', 'endings: meinen, meinem, meiner', 'case', '{1131}'::int[], 10, 23),
  (1141, 114, 'prepositions-1', 'in, nach, zu, bei: going places', 'preposition', '{}'::int[], 10, 24),
  (1142, 114, 'prepositions-2', 'für, ohne, um + accusative; mit, bei + dative', 'case', '{}'::int[], 10, 25),
  (1151, 115, 'perfekt-1', 'the participle: gemacht, gegessen', 'verb_form', '{}'::int[], 10, 26),
  (1152, 115, 'perfekt-2', 'haben or sein?', 'tense', '{}'::int[], 10, 27),
  (1153, 115, 'perfekt-3', 'the participle goes to the end', 'word_order', '{1041,1151}'::int[], 10, 28),
  (1161, 116, 'imperative-1', 'Komm! Kommt! Kommen Sie!', 'verb_form', '{}'::int[], 10, 29),
  (2011, 201, 'reflexive-verbs-1', 'mich, dich, sich, uns, euch', 'pronoun', '{}'::int[], 10, 30),
  (2021, 202, 'subordinate-clauses-1', 'weil, dass, wenn: the verb goes to the end', 'word_order', '{1041}'::int[], 10, 31),
  (2022, 202, 'subordinate-clauses-2', 'weil, dass, wenn, ob or denn?', 'other', '{}'::int[], 10, 32),
  (2023, 202, 'subordinate-clauses-3', 'subordinate clause first: verb, verb', 'word_order', '{2021,1042}'::int[], 10, 33),
  (2031, 203, 'two-way-prepositions-1', 'Wo? (dative) or Wohin? (accusative)', 'case', '{}'::int[], 10, 34),
  (2032, 203, 'two-way-prepositions-2', 'stellen/stehen, legen/liegen, hängen', 'verb_form', '{2031}'::int[], 10, 35),
  (2041, 204, 'dative-verbs-1', 'dative or accusative after the verb?', 'case', '{}'::int[], 10, 36),
  (2051, 205, 'perfekt-sein-1', 'sein in the Perfekt: movement, change, bleiben, passieren', 'tense', '{}'::int[], 10, 37),
  (2061, 206, 'praeteritum-basics-1', 'war, hatte, konnte, musste, wollte', 'tense', '{}'::int[], 10, 38),
  (2071, 207, 'comparative-superlative-1', 'schneller, am schnellsten (and the irregular ones)', 'adjective_ending', '{}'::int[], 10, 39),
  (2072, 207, 'comparative-superlative-2', 'als or wie?', 'other', '{}'::int[], 10, 40),
  (2081, 208, 'adjective-endings-1', 'after der/die/das: -e or -en', 'adjective_ending', '{}'::int[], 10, 41),
  (2082, 208, 'adjective-endings-2', 'after ein/kein/mein: -er, -es, -e, -en', 'adjective_ending', '{2081}'::int[], 10, 42),
  (2091, 209, 'polite-requests-1', 'hätte, könnte, würde: polite forms', 'mood', '{}'::int[], 10, 43),
  (2101, 210, 'verbs-with-prepositions-1', 'warten auf, sich freuen auf, Angst haben vor …', 'preposition', '{}'::int[], 10, 44),
  (2102, 210, 'verbs-with-prepositions-2', 'darauf, daran: worauf, woran', 'pronoun', '{2101}'::int[], 10, 45),
  (2111, 211, 'future-werden-1', 'werden + infinitive', 'verb_form', '{}'::int[], 10, 46),
  (2121, 212, 'zu-infinitive-1', 'zu + infinitive, and when not to use zu', 'verb_form', '{}'::int[], 10, 47),
  (3011, 301, 'genitive-1', 'des …(e)s, der: whose?', 'case', '{}'::int[], 10, 48),
  (3012, 301, 'genitive-2', 'wegen, trotz, während, statt + genitive', 'preposition', '{}'::int[], 10, 49),
  (3021, 302, 'relative-clauses-1', 'der, die, das, den, dem: which relative pronoun?', 'pronoun', '{}'::int[], 10, 50),
  (3022, 302, 'relative-clauses-2', 'verb at the end of the relative clause', 'word_order', '{3021,2021}'::int[], 10, 51),
  (3031, 303, 'passive-present-1', 'werden + participle: Das Paket wird geliefert.', 'verb_form', '{}'::int[], 10, 52),
  (3032, 303, 'passive-present-2', 'passive in the past: wurde + participle', 'tense', '{3031}'::int[], 10, 53),
  (3041, 304, 'konjunktiv-ii-1', 'wishes and hypotheticals: hätte, wäre, würde', 'mood', '{}'::int[], 10, 54),
  (3042, 304, 'konjunktiv-ii-2', 'advice and polite suggestions: solltest, könntest, würde', 'mood', '{}'::int[], 10, 55),
  (3051, 305, 'purpose-clauses-1', 'damit or um … zu?', 'other', '{}'::int[], 10, 56),
  (3061, 306, 'two-part-conjunctions-1', 'sowohl … als auch, weder … noch, entweder … oder …', 'other', '{}'::int[], 10, 57),
  (3071, 307, 'plusquamperfekt-1', 'hatte/war + participle: what had happened before', 'tense', '{}'::int[], 10, 58),
  (3081, 308, 'n-declension-1', 'den Kollegen, dem Nachbarn: masculine nouns with -n', 'case', '{}'::int[], 10, 59),
  (4011, 401, 'passive-alternatives-1', 'passive with modal verbs: muss erledigt werden', 'verb_form', '{3031}'::int[], 10, 60),
  (4012, 401, 'passive-alternatives-2', 'lässt sich, ist zu …, -bar: other ways to say "can be done"', 'verb_form', '{}'::int[], 10, 61),
  (4021, 402, 'konjunktiv-i-1', 'reported speech: er habe, sei, komme', 'mood', '{}'::int[], 10, 62),
  (4031, 403, 'nominalisation-1', 'verb → noun for formal texts: die Umsetzung des Plans', 'other', '{}'::int[], 10, 63),
  (4041, 404, 'participle-attributes-1', 'die steigenden Mieten, das gekaufte Buch', 'adjective_ending', '{}'::int[], 10, 64),
  (4051, 405, 'advanced-connectors-1', 'indem, sodass, falls, sofern, obwohl, je … desto', 'other', '{}'::int[], 10, 65),
  (4052, 405, 'advanced-connectors-2', 'trotzdem, deshalb, außerdem: connector first, then the verb', 'word_order', '{1042}'::int[], 10, 66),
  (4061, 406, 'modal-particles-1', 'doch, mal, ja, eben/halt, denn: what they add', 'other', '{}'::int[], 10, 67)
insert into public.vocabulary_words (id, german, english, part_of_speech, article, plural, cefr_level, frequency_rank, topic, example_sentence, example_translation, usage_note) values
  (2, 'sein', 'to be', 'verb', null, null, 'A1', 1, 'everyday', 'Das kann nicht sein!', 'That can''t be right!', 'Irregular: ich bin, du bist, er ist, wir sind.'),
  (10001, 'sein, seine', 'his, its', 'pronoun', null, null, 'A1', 2, 'people', 'Mein Kollege hat sein Auto verkauft.', 'My colleague sold his car.', 'Possessive for er/es. Endings like ein.'),
  (3, 'haben', 'to have', 'verb', null, null, 'A1', 3, 'everyday', 'Kann ich bitte die Rechnung haben?', 'Can I have the bill, please?', 'ich habe, du hast, er hat.'),
  (10002, 'und', 'and', 'conjunction', null, null, 'A1', 4, 'communication', 'Ich trinke Kaffee und mein Mann trinkt Tee.', 'I drink coffee and my husband drinks tea.', 'Does not change word order.'),
  (10003, 'ich', 'I', 'pronoun', null, null, 'A1', 5, 'communication', 'Ich heiße Anna und komme aus Polen.', 'My name is Anna and I''m from Poland.', 'Forms: mich (Akk), mir (Dat).'),
  (10004, 'sie', 'she, it (feminine nouns), they', 'pronoun', null, null, 'A1', 6, 'communication', 'Meine Schwester wohnt in Berlin. Sie ist Ärztin.', 'My sister lives in Berlin. She''s a doctor.', 'sie = she / they. Forms: sie (Akk), ihr (Dat, she) / ihnen (Dat, they).'),
  (10005, 'Sie', 'you (formal)', 'pronoun', null, null, 'A1', 7, 'communication', 'Können Sie mir bitte helfen?', 'Could you help me, please?', 'Register: formal. Always capitalised. Use with strangers, in shops, offices and at work unless offered du. Forms: Sie (Akk), Ihnen (Dat).'),
  (10006, 'nicht', 'not', 'adverb', null, null, 'A1', 8, 'communication', 'Ich verstehe das nicht.', 'I don''t understand that.', 'Negates verbs, adjectives and nouns with der/die/das. Nouns with ein / no article take kein.'),
  (10007, 'werden', 'to become, will (future), (passive)', 'verb', null, null, 'A1', 9, 'communication', 'Es wird kalt.', 'It''s getting cold.', 'du wirst, er wird. Future: Ich werde ... + infinitive. Passive auxiliary from B1. Forms: wird, wurde, ist geworden.'),
  (10008, 'es', 'it', 'pronoun', null, null, 'A1', 10, 'communication', 'Es regnet schon wieder.', 'It''s raining again.', 'Also the dummy subject: es gibt, es regnet, es geht.'),
  (10009, 'Es gibt', 'there is, there are', 'phrase', null, null, 'A1', 11, 'everyday', 'Gibt es hier in der Nähe eine Apotheke?', 'Is there a pharmacy near here?', 'es gibt + Akkusativ: Es gibt keinen Parkplatz.'),
  (30, 'können', 'can, to be able to', 'verb', null, null, 'A1', 12, 'everyday', 'Kannst du mir kurz helfen?', 'Can you help me for a moment?', 'ich kann, du kannst, er kann. The second verb goes to the end.'),
  (10010, 'wir', 'we', 'pronoun', null, null, 'A1', 13, 'communication', 'Wir treffen uns um acht vor dem Kino.', 'We''re meeting at eight in front of the cinema.', 'Forms: uns (Akk/Dat).'),
  (10011, 'er', 'he, it (masculine nouns)', 'pronoun', null, null, 'A1', 14, 'communication', 'Wo ist der Schlüssel? – Er liegt auf dem Tisch.', 'Where''s the key? – It''s on the table.', 'Refers to people and to masculine nouns. Forms: ihn (Akk), ihm (Dat).'),
  (10012, 'ihr, ihre', 'her, their', 'pronoun', null, null, 'A1', 15, 'people', 'Anna und ihre Kinder wohnen in Köln.', 'Anna and her children live in Cologne.', 'Possessive for sie (she/they). Capitalised Ihr = your (formal).'),
  (10013, 'Ihr, Ihre', 'your (formal)', 'pronoun', null, null, 'A1', 16, 'people', 'Wie ist Ihre Adresse?', 'What''s your address?', 'Register: formal. Possessive for Sie, always capitalised.'),
  (10014, 'ihr', 'you (informal, several people)', 'pronoun', null, null, 'A1', 17, 'communication', 'Habt ihr am Samstag Zeit?', 'Are you (guys) free on Saturday?', 'Verb ending -t: ihr habt, ihr kommt. Forms: euch (Akk/Dat).'),
  (10015, 'was', 'what', 'pronoun', null, null, 'A1', 18, 'communication', 'Was machst du am Wochenende?', 'What are you doing at the weekend?', 'Also short for etwas in speech: Ich hab was vergessen.'),
  (10016, 'wie', 'how, like, as', 'adverb', null, null, 'A1', 19, 'communication', 'Wie komme ich zum Bahnhof?', 'How do I get to the station?', 'Also in comparisons: so groß wie = as big as.'),
  (120, 'auch', 'also, too', 'adverb', null, null, 'A1', 20, 'everyday', 'Ich komme auch mit.', 'I''m coming too.', null),
  (31, 'müssen', 'must, to have to', 'verb', null, null, 'A1', 21, 'everyday', 'Ich muss heute länger arbeiten.', 'I have to work late today.', 'ich muss, du musst, er muss.'),
  (92, 'wollen', 'to want', 'verb', null, null, 'A1', 22, 'everyday', 'Wir wollen am Samstag ins Kino.', 'We want to go to the cinema on Saturday.', 'ich will, du willst, er will. Not ''will'' as in English future!'),
  (10017, 'mein, meine', 'my', 'pronoun', null, null, 'A1', 23, 'people', 'Das ist meine Wohnung.', 'This is my flat.', 'Possessive, endings like ein: mein Bruder, meine Schwester, meinen Bruder (Akk).'),
  (122, 'noch', 'still; yet', 'adverb', null, null, 'A1', 24, 'time', 'Ich bin noch im Büro.', 'I''m still at the office.', null),
  (117, 'hier', 'here', 'adverb', null, null, 'A1', 25, 'everyday', 'Wohnen Sie hier?', 'Do you live here?', null),
  (10018, 'nur', 'only, just', 'adverb', null, null, 'A1', 26, 'communication', 'Ich habe nur zehn Euro dabei.', 'I''ve only got ten euros on me.', null),
  (10019, 'sollen', 'should, to be supposed to', 'verb', null, null, 'A1', 27, 'communication', 'Der Arzt sagt, ich soll mehr trinken.', 'The doctor says I should drink more.', 'Modal verb: ich soll, du sollst. Reports what someone else wants. Forms: soll, sollte, hat gesollt.'),
  (10020, 'kein, keine', 'no, not a, not any', 'pronoun', null, null, 'A1', 28, 'communication', 'Ich habe heute keine Zeit.', 'I don''t have time today.', 'Negates nouns that would have ein or no article. Same endings as ein, plus plural keine.'),
  (134, 'aber', 'but', 'conjunction', null, null, 'A1', 29, 'communication', 'Ich bin müde, aber ich muss noch arbeiten.', 'I''m tired, but I still have to work.', null),
  (135, 'oder', 'or', 'conjunction', null, null, 'A1', 30, 'communication', 'Möchtest du Tee oder Kaffee?', 'Would you like tea or coffee?', null),
  (10021, 'mehr', 'more', 'adverb', null, null, 'A1', 31, 'communication', 'Kann ich noch mehr Wasser haben?', 'Can I have some more water?', 'Comparative of viel. nicht mehr = no longer.'),
  (10022, 'viel, viele', 'much, many, a lot', 'pronoun', null, null, 'A1', 32, 'communication', 'Wir haben viel Arbeit und viele Termine.', 'We have a lot of work and many appointments.', 'viel + singular (viel Zeit), viele + plural (viele Leute). Comparative mehr.'),
  (10023, 'wie viel', 'how much, how many', 'adverb', null, null, 'A1', 33, 'communication', 'Wie viel kostet das?', 'How much does that cost?', 'Written as two words wie viele + plural: Wie viele Leute kommen?'),
  (10024, 'da', 'then, there, here', 'adverb', null, null, 'A1', 34, 'everyday', 'Ist Herr Weber da?', 'Is Mr Weber there?', 'In speech often instead of dort or hier. da sein = to be present.'),
  (121, 'schon', 'already', 'adverb', null, null, 'A1', 35, 'time', 'Bist du schon fertig?', 'Are you finished already?', null),
  (10025, 'man', 'one, you, people (in general)', 'pronoun', null, null, 'A1', 36, 'communication', 'Hier darf man nicht parken.', 'You can''t park here.', 'Generic subject, verb in 3rd person singular. Very common in instructions and rules.'),
  (10026, 'dann', 'then', 'adverb', null, null, 'A1', 37, 'time', 'Erst essen wir, dann gehen wir ins Kino.', 'First we''ll eat, then we''ll go to the cinema.', 'Also: Dann bis morgen! = See you tomorrow then.'),
  (10027, 'ja', 'yes, (particle) as you know', 'adverb', null, null, 'A1', 38, 'communication', 'Ja, gern.', 'Yes, please.', 'Also a particle: Das ist ja toll! = That''s great!'),
  (10028, 'unser, unsere', 'our', 'pronoun', null, null, 'A1', 39, 'people', 'Unsere Nachbarn sind sehr nett.', 'Our neighbours are very nice.', 'Endings like ein.'),
  (113, 'immer', 'always', 'adverb', null, null, 'A1', 40, 'time', 'Der Bus ist immer pünktlich.', 'The bus is always on time.', null),
  (42, 'jetzt', 'now', 'adverb', null, null, 'A1', 41, 'time', 'Ich habe jetzt leider keine Zeit.', 'Unfortunately I don''t have time right now.', null),
  (119, 'sehr', 'very', 'adverb', null, null, 'A1', 42, 'everyday', 'Vielen Dank, das ist sehr nett.', 'Thank you, that''s very kind.', null),
  (1075, 'bis', 'until', 'preposition', null, null, 'A1', 43, 'time', 'Ich arbeite heute bis sechs.', 'I''m working until six today.', null),
  (10029, 'durch', 'through', 'preposition', null, null, 'A1', 44, 'communication', 'Wir gehen durch den Park nach Hause.', 'We walk home through the park.', 'Always + Akkusativ.'),
  (10030, 'denn', '(question particle), because', 'conjunction', null, null, 'A1', 45, 'communication', 'Ich bleibe zu Hause, denn ich bin krank.', 'I''m staying home because I''m ill.', 'Conjunction without verb-final order. In questions a softening particle: Was ist denn los?'),
  (10031, 'dein, deine', 'your (informal, one person)', 'pronoun', null, null, 'A1', 46, 'people', 'Ist das dein Handy?', 'Is that your phone?', 'Possessive for du. Endings like ein.'),
  (10032, 'mögen', 'to like', 'verb', null, null, 'A1', 47, 'people', 'Ich mag keinen Fisch.', 'I don''t like fish.', 'ich mag, du magst. With nouns. For activities use gern. Forms: mag, mochte, hat gemocht.'),
  (10033, 'wer', 'who', 'pronoun', null, null, 'A1', 48, 'communication', 'Wer ist das auf dem Foto?', 'Who''s that in the photo?', 'Forms: wen (Akk), wem (Dat).'),
  (10034, 'ab', 'from (a time or place)', 'preposition', null, null, 'A1', 49, 'communication', 'Ab Montag habe ich Urlaub.', 'I''m on holiday from Monday.', 'ab sofort = starting now. Also as verb prefix (abfahren).'),
  (10035, 'also', 'so, well, therefore', 'adverb', null, null, 'A1', 50, 'communication', 'Also, wann treffen wir uns?', 'So, when are we meeting?', 'Register: spoken. Discourse marker to start or conclude. Not English ''also'' (= auch).'),
  (10036, 'wo', 'where', 'adverb', null, null, 'A1', 51, 'communication', 'Wo ist hier die Toilette?', 'Where is the toilet here?', 'Location. Movement uses wohin, origin woher.'),
  (10037, 'nichts', 'nothing', 'pronoun', null, null, 'A1', 52, 'communication', 'Ich habe heute noch nichts gegessen.', 'I haven''t eaten anything yet today.', null),
  (4, 'heute', 'today', 'adverb', null, null, 'A1', 53, 'time', 'Heute habe ich keine Zeit.', 'I don''t have time today.', null),
  (10038, 'warum', 'why', 'adverb', null, null, 'A1', 54, 'communication', 'Warum bist du so müde?', 'Why are you so tired?', null),
  (10039, 'dürfen', 'may, to be allowed to', 'verb', null, null, 'A1', 55, 'communication', 'Darf ich hier rauchen?', 'May I smoke here?', 'Modal verb: ich darf, du darfst. nicht dürfen = must not. Forms: darf, durfte, hat gedurft.'),
  (1074, 'seit', 'since; for (time up to now)', 'preposition', null, null, 'A1', 56, 'time', 'Ich wohne seit drei Jahren in Berlin.', 'I''ve lived in Berlin for three years.', 'seit + Dativ, with present tense in German.'),
  (10040, 'nein', 'no', 'adverb', null, null, 'A1', 57, 'communication', 'Nein, danke.', 'No, thank you.', null),
  (10041, 'beide', 'both', 'pronoun', null, null, 'A1', 58, 'communication', 'Beide Kinder gehen schon zur Schule.', 'Both children already go to school.', null),
  (127, 'ohne', 'without', 'preposition', null, null, 'A1', 59, 'everyday', 'Ich trinke Kaffee ohne Zucker.', 'I drink coffee without sugar.', 'ohne + Akkusativ.'),
  (118, 'dort', 'there', 'adverb', null, null, 'A1', 60, 'everyday', 'Dort drüben ist der Bahnhof.', 'The station is over there.', null),
  (10042, 'doch', 'yes (contradicting), after all, (emphasis)', 'adverb', null, null, 'A1', 61, 'communication', 'Kommst du nicht mit? – Doch!', 'Aren''t you coming? – Yes, I am!', 'Register: spoken. Answers a negative question with ''yes''. As a particle: Komm doch mit! = Do come along!'),
  (10043, 'so', 'like this, so, such', 'adverb', null, null, 'A1', 62, 'communication', 'Das macht man so.', 'You do it like this.', 'In speech often a filler: So, jetzt fangen wir an.'),
  (10044, 'wieder', 'again, back', 'adverb', null, null, 'A1', 63, 'time', 'Der Aufzug ist schon wieder kaputt.', 'The lift is broken again.', null),
  (116, 'nie', 'never', 'adverb', null, null, 'A1', 64, 'time', 'Abends trinke ich nie Kaffee.', 'I never drink coffee in the evening.', null),
  (10045, 'ganz', 'completely, quite, whole', 'adverb', null, null, 'A1', 65, 'communication', 'Das Essen war ganz gut.', 'The food was quite good.', 'ganz = ''quite'' with positive adjectives, ''completely'' otherwise (ganz neu). As adjective: der ganze Tag.'),
  (10046, 'gleich', 'right away, in a moment, same', 'adverb', null, null, 'A1', 66, 'time', 'Ich komme gleich!', 'I''ll be right there!', 'As adjective: the same (das gleiche Problem).'),
  (10047, 'mal', '(softening particle), just, times', 'adverb', null, null, 'A1', 67, 'communication', 'Kannst du mal kurz kommen?', 'Can you come here for a sec?', 'Register: spoken. Softens requests: Warte mal! Also: dreimal = three times.'),
  (10048, 'Mal', 'time (occasion)', 'noun', 'das', 'Male', 'A1', 68, 'time', 'Das war das erste Mal.', 'That was the first time.', 'jedes Mal = every time zum ersten Mal = for the first time.'),
  (123, 'zusammen', 'together', 'adverb', null, null, 'A1', 69, 'people', 'Wir wohnen seit zwei Jahren zusammen.', 'We''ve been living together for two years.', null),
  (126, 'vielleicht', 'maybe, perhaps', 'adverb', null, null, 'A1', 70, 'communication', 'Vielleicht komme ich später.', 'Maybe I''ll come later.', null),
  (10049, 'erst', 'only (not until), first', 'adverb', null, null, 'A1', 71, 'time', 'Der Zug kommt erst um zehn.', 'The train doesn''t come until ten.', 'Time: erst = ''only/not until'' zuerst/erst = first.'),
  (13, 'gehen', 'to go (on foot), to walk', 'verb', null, null, 'A1', 72, 'everyday', 'Ich muss jetzt nach Hause gehen.', 'I have to go home now.', null),
  (16, 'machen', 'to do, to make', 'verb', null, null, 'A1', 73, 'everyday', 'Was willst du am Wochenende machen?', 'What do you want to do at the weekend?', null),
  (17, 'gut', 'good, well', 'adjective', null, null, 'A1', 74, 'everyday', 'Das Essen hier ist wirklich gut.', 'The food here is really good.', null),
  (10050, 'jeder, jede, jedes', 'every, each', 'pronoun', null, null, 'A1', 75, 'communication', 'Der Bus fährt jeden Tag um sieben.', 'The bus runs every day at seven.', 'Singular only. Endings like der/die/das.'),
  (1076, 'zwischen', 'between', 'preposition', null, null, 'A1', 76, 'travel', 'Der Supermarkt ist zwischen der Bank und der Post.', 'The supermarket is between the bank and the post office.', null),
  (15, 'kommen', 'to come', 'verb', null, null, 'A1', 77, 'everyday', 'Kannst du heute Abend kommen?', 'Can you come this evening?', null),
  (57, 'sagen', 'to say, to tell', 'verb', null, null, 'A1', 78, 'communication', 'Kannst du mir sagen, wie spät es ist?', 'Can you tell me what time it is?', null),
  (95, 'geben', 'to give', 'verb', null, null, 'A1', 79, 'everyday', 'Kannst du mir das Salz geben?', 'Can you pass me the salt?', 'jemandem (Dativ) etwas (Akkusativ) geben. es gibt = there is.'),
  (1067, 'sofort', 'immediately, right away', 'adverb', null, null, 'A1', 80, 'time', 'Ich komme sofort!', 'I''m coming right away!', null),
  (114, 'oft', 'often', 'adverb', null, null, 'A1', 81, 'time', 'Wir gehen oft zusammen essen.', 'We often go out to eat together.', null),
  (90, 'sehen', 'to see', 'verb', null, null, 'A1', 82, 'everyday', 'Kann ich mal die Fotos sehen?', 'Can I have a look at the photos?', 'du siehst, er sieht.'),
  (10051, 'euer, eure', 'several people), your (informal', 'pronoun', null, null, 'A1', 83, 'people', 'Wo ist euer Auto?', 'Where is your car?', 'Possessive for ihr (you all). euer → eure (the e drops).'),
  (10052, 'sicher', 'sure, safe, certain', 'adjective', null, null, 'A1', 84, 'communication', 'Bist du sicher?', 'Are you sure?', 'Also safe: Ist das sicher?'),
  (54, 'wissen', 'to know (a fact)', 'verb', null, null, 'A1', 85, 'communication', 'Ich will wissen, wann der Zug kommt.', 'I want to know when the train is coming.', 'ich weiß, du weißt, er weiß. For people and places use kennen.'),
  (41, 'morgen', 'tomorrow', 'adverb', null, null, 'A1', 86, 'time', 'Morgen fahre ich nach Köln.', 'Tomorrow I''m going to Cologne.', 'Lower case morgen = tomorrow; der Morgen = the morning.'),
  (10053, 'Morgen', 'morning', 'noun', 'der', 'Morgen', 'A1', 87, 'time', 'Am Morgen trinke ich immer Kaffee.', 'In the morning I always drink coffee.', 'Capital M = the morning lower-case morgen = tomorrow. morgens = in the mornings.'),
  (82, 'Jahr', 'year', 'noun', 'das', 'Jahre', 'A1', 88, 'time', 'Ich lerne seit einem Jahr Deutsch.', 'I''ve been learning German for a year.', null),
  (99, 'finden', 'to find; to think (opinion)', 'verb', null, null, 'A1', 89, 'everyday', 'Ich kann mein Handy nicht finden.', 'I can''t find my phone.', 'Ich finde das gut = I think that''s good.'),
  (10054, 'bald', 'soon', 'adverb', null, null, 'A1', 90, 'time', 'Bis bald!', 'See you soon!', null),
  (10055, 'genau', 'exactly, precisely, (agreement) right', 'adverb', null, null, 'A1', 91, 'communication', 'Genau, so machen wir das.', 'Exactly, that''s how we''ll do it.', 'Register: spoken. Very common in speech to agree: Genau!'),
  (10056, 'welcher, welche, welches', 'which', 'pronoun', null, null, 'A1', 92, 'communication', 'Welchen Bus muss ich nehmen?', 'Which bus do I have to take?', 'Question word with der-endings.'),
  (10057, 'wann', 'when', 'adverb', null, null, 'A1', 93, 'communication', 'Wann fährt der nächste Zug nach Hamburg?', 'When does the next train to Hamburg leave?', 'Question word only. For ''when'' in statements use wenn/als.'),
  (10058, 'laut', 'loud, noisy', 'adjective', null, null, 'A1', 94, 'home', 'Die Musik ist zu laut.', 'The music is too loud.', 'As preposition: according to (laut Vertrag).'),
  (10059, 'tun', 'to put, to do', 'verb', null, null, 'A1', 95, 'everyday', 'Was kann ich für Sie tun?', 'What can I do for you?', 'Es tut mir leid. = I''m sorry. Es tut weh. = It hurts. Forms: tut, tat, hat getan.'),
  (21, 'Zeit', 'time', 'noun', 'die', null, 'A1', 96, 'time', 'Hast du heute Abend Zeit?', 'Are you free this evening?', null),
  (10060, 'stehen', 'to stand, to be (written)', 'verb', null, null, 'A1', 97, 'everyday', 'Das steht im Vertrag.', 'That''s in the contract.', 'Also: Das Kleid steht dir. = The dress suits you. Forms: steht, stand, hat gestanden.'),
  (65, 'neu', 'new', 'adjective', null, null, 'A1', 98, 'everyday', 'Mein Handy ist ganz neu.', 'My phone is brand new.', null),
  (63, 'groß', 'big, tall', 'adjective', null, null, 'A1', 99, 'everyday', 'Die Wohnung ist groß und hell.', 'The flat is big and bright.', null),
  (10061, 'leben', 'to live, to be alive', 'verb', null, null, 'A1', 100, 'people', 'Meine Eltern leben in Polen.', 'My parents live in Poland.', 'Forms: lebt, lebte, hat gelebt.'),
  (29, 'Tag', 'day', 'noun', 'der', 'Tage', 'A1', 101, 'time', 'Ich wünsche dir einen schönen Tag!', 'Have a nice day!', null),
  (10062, 'Mann', 'man, husband', 'noun', 'der', 'Männer', 'A1', 102, 'people', 'Mein Mann arbeitet bei Siemens.', 'My husband works at Siemens.', null),
  (49, 'Kind', 'child', 'noun', 'das', 'Kinder', 'A1', 103, 'people', 'Unser Kind geht schon in die Schule.', 'Our child already goes to school.', null),
  (10063, 'natürlich', 'of course, naturally', 'adverb', null, null, 'A1', 104, 'communication', 'Natürlich helfe ich dir.', 'Of course I''ll help you.', null),
  (10064, 'einfach', 'simple, easy, simply', 'adjective', null, null, 'A1', 105, 'everyday', 'Das ist ganz einfach.', 'That''s really simple.', 'As adverb: simply/just. eine einfache Fahrt = a one-way ticket.'),
  (10065, 'Mensch', 'person, human being', 'noun', 'der', 'Menschen', 'A1', 106, 'people', 'Er ist ein sehr netter Mensch.', 'He''s a very nice person.', 'n-declension: den/dem Menschen.'),
  (96, 'nehmen', 'to take', 'verb', null, null, 'A1', 107, 'transport', 'Wir können den Bus um acht nehmen.', 'We can take the bus at eight.', 'du nimmst, er nimmt.'),
  (10066, 'hören', 'to hear, to listen to', 'verb', null, null, 'A1', 108, 'communication', 'Ich höre gern Musik.', 'I like listening to music.', 'Forms: hört, hörte, hat gehört.'),
  (74, 'Frau', 'woman; wife; Mrs', 'noun', 'die', 'Frauen', 'A1', 109, 'people', 'Die Frau am Empfang ist sehr freundlich.', 'The woman at reception is very friendly.', null),
  (94, 'bringen', 'to bring', 'verb', null, null, 'A1', 110, 'food', 'Können Sie mir bitte noch ein Glas Wasser bringen?', 'Could you bring me another glass of water, please?', null),
  (10067, 'zwei', 'two', 'adjective', null, null, 'A1', 111, 'everyday', 'Ich habe zwei Kinder.', 'I have two children.', 'On the phone often zwo, to avoid confusion with drei.'),
  (45, 'brauchen', 'to need', 'verb', null, null, 'A1', 112, 'everyday', 'Wir werden mehr Zeit brauchen.', 'We''re going to need more time.', null),
  (93, 'bleiben', 'to stay', 'verb', null, null, 'A1', 113, 'everyday', 'Kannst du heute länger bleiben?', 'Can you stay longer today?', null),
  (64, 'klein', 'small, little', 'adjective', null, null, 'A1', 114, 'everyday', 'Das Zimmer ist leider sehr klein.', 'Unfortunately the room is very small.', null),
  (10068, 'Haus', 'house, building', 'noun', 'das', 'Häuser', 'A1', 115, 'home', 'Das Haus hat einen schönen Garten.', 'The house has a lovely garden.', 'nach Hause = (going) home zu Hause = at home.'),
  (111, 'gestern', 'yesterday', 'adverb', null, null, 'A1', 116, 'time', 'Gestern war ich beim Arzt.', 'Yesterday I was at the doctor''s.', null),
  (10069, 'fast', 'almost, nearly', 'adverb', null, null, 'A1', 117, 'communication', 'Ich bin fast fertig.', 'I''m almost finished.', null),
  (10070, 'weit', 'far, wide', 'adjective', null, null, 'A1', 118, 'everyday', 'Ist es weit bis zum Zentrum?', 'Is it far to the centre?', null),
  (10071, 'bitten', 'to ask (for), to request', 'verb', null, null, 'A1', 119, 'communication', 'Darf ich Sie um einen Gefallen bitten?', 'May I ask you a favour?', 'bitten um + Akk = to ask for. Forms: bittet, bat, hat gebeten.'),
  (10072, 'woher', 'where from', 'adverb', null, null, 'A1', 120, 'communication', 'Woher kommen Sie?', 'Where are you from?', null),
  (33, 'helfen', 'to help', 'verb', null, null, 'A1', 121, 'everyday', 'Kannst du mir bitte helfen?', 'Can you help me, please?', 'helfen + Dativ: Ich helfe dir (not dich).'),
  (10073, 'hinter', 'behind', 'preposition', null, null, 'A1', 122, 'communication', 'Der Parkplatz ist hinter dem Haus.', 'The car park is behind the building.', 'Two-way preposition.'),
  (35, 'sprechen', 'to speak', 'verb', null, null, 'A1', 123, 'communication', 'Können Sie bitte langsamer sprechen?', 'Could you speak more slowly, please?', 'du sprichst, er spricht.'),
  (10074, 'zurück', 'back', 'adverb', null, null, 'A1', 124, 'everyday', 'Ich bin um sechs zurück.', 'I''ll be back at six.', 'Also a verb prefix: zurückrufen, zurückgeben.'),
  (10075, 'niemand', 'nobody, no one', 'pronoun', null, null, 'A1', 125, 'people', 'Niemand hat angerufen.', 'Nobody called.', null),
  (10076, 'liegen', 'to lie, to be (located)', 'verb', null, null, 'A1', 126, 'everyday', 'Das Hotel liegt direkt am Bahnhof.', 'The hotel is right by the station.', 'Position (wo?). The action is legen. Forms: liegt, lag, hat gelegen.'),
  (10077, 'weiter', 'further, on, continue', 'adverb', null, null, 'A1', 127, 'everyday', 'Gehen Sie hier weiter bis zur Ampel.', 'Carry on down here as far as the traffic lights.', 'Common as verb prefix: weitermachen, weitergehen.'),
  (10078, 'gerade', 'just, right now, straight', 'adverb', null, null, 'A1', 128, 'time', 'Ich bin gerade beim Einkaufen.', 'I''m doing the shopping right now.', 'gerade = at the moment / just now as adjective: straight, even.'),
  (10079, 'glauben', 'to believe, to think', 'verb', null, null, 'A1', 129, 'communication', 'Ich glaube, er kommt heute nicht.', 'I think he isn''t coming today.', '+Dat (person): Ich glaube dir. Forms: glaubt, glaubte, hat geglaubt.'),
  (23, 'arbeiten', 'to work', 'verb', null, null, 'A1', 130, 'work', 'Ich muss morgen bis sechs arbeiten.', 'I have to work until six tomorrow.', null),
  (66, 'alt', 'old', 'adjective', null, null, 'A1', 131, 'everyday', 'Das Haus ist schon sehr alt.', 'The house is already very old.', null),
  (55, 'kennen', 'to know (a person or place)', 'verb', null, null, 'A1', 132, 'people', 'Du musst den Film kennen, er ist sehr bekannt.', 'You must know the film, it''s very famous.', 'kennen = be familiar with; wissen = know a fact.'),
  (10080, 'bekommen', 'to get, to receive', 'verb', null, null, 'A1', 133, 'everyday', 'Ich habe eine E-Mail vom Vermieter bekommen.', 'I got an email from the landlord.', 'Not ''become'' (= werden). Forms: bekommt, bekam, hat bekommen.'),
  (108, 'richtig', 'right, correct', 'adjective', null, null, 'A1', 134, 'communication', 'Ist die Adresse richtig?', 'Is the address correct?', null),
  (10081, 'drei', 'three', 'adjective', null, null, 'A1', 135, 'everyday', 'Das kostet drei Euro.', 'That costs three euros.', null),
  (10082, 'hoch', 'high, tall', 'adjective', null, null, 'A1', 136, 'everyday', 'Die Miete ist sehr hoch.', 'The rent is very high.', 'Before nouns: hoh- (ein hohes Gebäude). Comparative höher. Forms: höher, am höchsten.'),
  (102, 'schnell', 'fast, quick', 'adjective', null, null, 'A1', 137, 'transport', 'Der Zug ist sehr schnell.', 'The train is very fast.', null),
  (10083, 'du', 'one person), you (informal', 'pronoun', null, null, 'A1', 138, 'communication', 'Kommst du heute Abend mit?', 'Are you coming along this evening?', 'Forms: dich (Akk), dir (Dat). Used with friends, family, children and many colleagues.'),
  (10084, 'spielen', 'to play', 'verb', null, null, 'A1', 139, 'travel', 'Die Kinder spielen im Garten.', 'The children are playing in the garden.', 'Forms: spielt, spielte, hat gespielt.'),
  (11, 'Geld', 'money', 'noun', 'das', null, 'A1', 140, 'shopping', 'Ich habe kein Geld dabei.', 'I don''t have any money on me.', null),
  (1032, 'Problem', 'problem', 'noun', 'das', 'Probleme', 'A1', 141, 'everyday', 'Wir haben ein kleines Problem mit der Heizung.', 'We have a small problem with the heating.', null),
  (10085, 'spät', 'late', 'adjective', null, null, 'A1', 142, 'time', 'Wie spät ist es?', 'What time is it?', 'zu spät kommen = to be late. Forms: später, am spätesten.'),
  (6, 'Arbeit', 'work (the place or activity)', 'noun', 'die', null, 'A1', 143, 'work', 'Ich fahre mit dem Fahrrad zur Arbeit.', 'I cycle to work.', null),
  (10086, 'stellen', 'to put (upright), to place', 'verb', null, null, 'A1', 144, 'everyday', 'Stell die Tasche bitte auf den Stuhl.', 'Put the bag on the chair, please.', 'Action (wohin? + Akk), for upright things. eine Frage stellen = to ask a question. Forms: stellt, stellte, hat gestellt.'),
  (77, 'Stadt', 'city, town', 'noun', 'die', 'Städte', 'A1', 145, 'travel', 'Die Stadt ist am Wochenende sehr voll.', 'The city is very crowded at the weekend.', null),
  (124, 'gern', 'gladly (Ich koche gern = I like cooking)', 'adverb', null, null, 'A1', 146, 'everyday', 'Ich koche gern für Freunde.', 'I like cooking for friends.', 'verb + gern = like doing something.'),
  (104, 'schön', 'beautiful, nice', 'adjective', null, null, 'A1', 147, 'everyday', 'Das Wetter ist heute schön.', 'The weather is nice today.', null),
  (107, 'wichtig', 'important', 'adjective', null, null, 'A1', 148, 'work', 'Der Termin ist sehr wichtig.', 'The appointment is very important.', null),
  (10087, 'jung', 'young', 'adjective', null, null, 'A1', 149, 'people', 'Meine Kollegen sind alle sehr jung.', 'My colleagues are all very young.', 'Comparative jünger. Forms: jünger, am jüngsten.'),
  (10088, 'lang', 'long', 'adjective', null, null, 'A1', 150, 'time', 'Wir haben lange gewartet.', 'We waited a long time.', 'Adverb lange = for a long time. Comparative länger. Forms: länger, am längsten.'),
  (10089, 'Land', 'country, land, countryside', 'noun', 'das', 'Länder', 'A1', 151, 'everyday', 'Aus welchem Land kommen Sie?', 'Which country are you from?', 'auf dem Land = in the countryside. Also: Bundesland.'),
  (10090, 'wohin', 'where (to)', 'adverb', null, null, 'A1', 152, 'communication', 'Wohin fährst du im Urlaub?', 'Where are you going on holiday?', null),
  (34, 'verstehen', 'to understand', 'verb', null, null, 'A1', 153, 'communication', 'Ich kann dich leider nicht verstehen.', 'Sorry, I can''t understand you.', null),
  (39, 'Freund', 'friend; boyfriend', 'noun', 'der', 'Freunde', 'A1', 154, 'people', 'Am Wochenende besuche ich einen Freund.', 'At the weekend I''m visiting a friend.', 'A female friend: die Freundin.'),
  (40, 'Woche', 'week', 'noun', 'die', 'Wochen', 'A1', 155, 'time', 'Nächste Woche habe ich Urlaub.', 'I''m on holiday next week.', null),
  (10091, 'heißen', 'to be called, to mean', 'verb', null, null, 'A1', 156, 'people', 'Wie heißen Sie?', 'What''s your name?', 'Was heißt das? = What does that mean? Forms: heißt, hieß, hat geheißen.'),
  (10092, 'neben', 'next to', 'preposition', null, null, 'A1', 157, 'communication', 'Die Apotheke ist neben der Bank.', 'The pharmacy is next to the bank.', 'Two-way preposition.'),
  (10093, 'Ende', 'end', 'noun', 'das', 'Enden', 'A1', 158, 'time', 'Ende Mai ziehe ich um.', 'I''m moving at the end of May.', null),
  (52, 'Uhr', 'clock, watch; o''clock', 'noun', 'die', 'Uhren', 'A1', 159, 'time', 'Wir treffen uns um acht Uhr.', 'We''re meeting at eight o''clock.', null),
  (10094, 'Leute', 'people', 'noun', 'die', null, 'A1', 160, 'people', 'Auf der Party waren viele Leute.', 'There were lots of people at the party.', 'Plural only.'),
  (98, 'suchen', 'to look for, to search', 'verb', null, null, 'A1', 161, 'everyday', 'Kannst du mir helfen, meinen Schlüssel zu suchen?', 'Can you help me look for my key?', null),
  (10095, 'laufen', 'to run, to walk, to be running/on', 'verb', null, null, 'A1', 162, 'everyday', 'Wir laufen zum Bahnhof, es ist nicht weit.', 'We''ll walk to the station, it isn''t far.', 'du läufst. Also: Was läuft im Kino? = What''s on? Forms: läuft, lief, ist gelaufen.'),
  (75, 'Name', 'name', 'noun', 'der', 'Namen', 'A1', 163, 'people', 'Wie ist Ihr Name, bitte?', 'What''s your name, please?', null),
  (9, 'Familie', 'family', 'noun', 'die', 'Familien', 'A1', 164, 'people', 'Meine Familie wohnt in Hamburg.', 'My family lives in Hamburg.', null),
  (10096, 'einmal', 'once, one time', 'adverb', null, null, 'A1', 165, 'time', 'Ich war einmal in München.', 'I''ve been to Munich once.', 'In speech shortened to mal. noch einmal = once more.'),
  (10097, 'Frage', 'question', 'noun', 'die', 'Fragen', 'A1', 166, 'communication', 'Ich habe eine Frage.', 'I have a question.', null),
  (14, 'fahren', 'to go (by vehicle), to drive', 'verb', null, null, 'A1', 167, 'transport', 'Morgen will ich mit dem Zug nach München fahren.', 'Tomorrow I want to take the train to Munich.', 'Stem change: du fährst, er fährt.'),
  (10098, 'kurz', 'short, brief', 'adjective', null, null, 'A1', 168, 'time', 'Ich habe eine kurze Frage.', 'I have a quick question.', 'kurz = for a moment: Warte kurz! Forms: kürzer, am kürzesten.'),
  (10099, 'Vater', 'father', 'noun', 'der', 'Väter', 'A1', 169, 'people', 'Mein Vater ist Rentner.', 'My father is retired.', 'Informal: Papa.'),
  (10100, 'Stunde', 'hour, lesson', 'noun', 'die', 'Stunden', 'A1', 170, 'time', 'Die Fahrt dauert eine Stunde.', 'The journey takes an hour.', null),
  (10101, 'Hand', 'hand', 'noun', 'die', 'Hände', 'A1', 171, 'people', 'Wasch dir bitte die Hände.', 'Please wash your hands.', null),
  (10102, 'Mutter', 'mother', 'noun', 'die', 'Mütter', 'A1', 172, 'people', 'Meine Mutter ruft jeden Sonntag an.', 'My mother calls every Sunday.', 'Informal: Mama.'),
  (10103, 'Minute', 'minute', 'noun', 'die', 'Minuten', 'A1', 173, 'time', 'Der Bus kommt in fünf Minuten.', 'The bus comes in five minutes.', null),
  (87, 'lernen', 'to learn, to study', 'verb', null, null, 'A1', 174, 'everyday', 'Ich möchte jeden Tag ein bisschen Deutsch lernen.', 'I''d like to learn a little German every day.', null),
  (10104, 'Schule', 'school', 'noun', 'die', 'Schulen', 'A1', 175, 'work', 'Die Kinder sind noch in der Schule.', 'The children are still at school.', null),
  (10105, 'Hilfe', 'help', 'noun', 'die', null, 'A1', 176, 'everyday', 'Danke für deine Hilfe!', 'Thanks for your help!', 'Hilfe! = Help!'),
  (56, 'fragen', 'to ask', 'verb', null, null, 'A1', 177, 'communication', 'Du kannst mich immer fragen.', 'You can always ask me.', null),
  (10106, 'erzählen', 'to tell, to recount', 'verb', null, null, 'A1', 178, 'communication', 'Erzähl mal, wie war der Urlaub?', 'Tell me, how was the holiday?', 'erzählen von / über. Forms: erzählt, erzählte, hat erzählt.'),
  (10107, 'schwer', 'heavy, difficult', 'adjective', null, null, 'A1', 179, 'everyday', 'Die Prüfung war schwer.', 'The exam was difficult.', null),
  (88, 'schreiben', 'to write', 'verb', null, null, 'A1', 180, 'communication', 'Kannst du mir die Adresse schreiben?', 'Can you write down the address for me?', null),
  (10108, 'Nacht', 'night', 'noun', 'die', 'Nächte', 'A1', 181, 'time', 'Gute Nacht!', 'Good night!', null),
  (115, 'manchmal', 'sometimes', 'adverb', null, null, 'A1', 182, 'time', 'Manchmal arbeite ich von zu Hause.', 'Sometimes I work from home.', null),
  (1048, 'danken', 'to thank', 'verb', null, null, 'A1', 183, 'communication', 'Ich möchte dir für alles danken.', 'I''d like to thank you for everything.', 'danken + Dativ: Ich danke dir.'),
  (10109, 'Herr', 'gentleman, Mr', 'noun', 'der', 'Herren', 'A1', 184, 'people', 'Herr Weber, Ihr Termin ist um zehn.', 'Mr Weber, your appointment is at ten.', 'n-declension: dem Herrn. Sehr geehrte Damen und Herren = Dear Sir or Madam.'),
  (1054, 'warten', 'to wait', 'verb', null, null, 'A1', 185, 'transport', 'Wir müssen noch auf den Bus warten.', 'We still have to wait for the bus.', 'warten auf + Akkusativ.'),
  (78, 'Auto', 'car', 'noun', 'das', 'Autos', 'A1', 186, 'transport', 'Wir fahren mit dem Auto in den Urlaub.', 'We''re driving on holiday.', null),
  (10110, 'Film', 'film, movie', 'noun', 'der', 'Filme', 'A1', 187, 'travel', 'Der Film war echt gut.', 'The film was really good.', null),
  (10111, 'denken', 'to think', 'verb', null, null, 'A1', 188, 'communication', 'Was denkst du?', 'What do you think?', 'denken an + Akk = to think of. Forms: denkt, dachte, hat gedacht.'),
  (10112, 'Mädchen', 'girl', 'noun', 'das', 'Mädchen', 'A1', 189, 'people', 'Das Mädchen ist sieben Jahre alt.', 'The girl is seven years old.', 'Neuter because of -chen.'),
  (10113, 'Wort', 'word', 'noun', 'das', 'Wörter', 'A1', 190, 'communication', 'Was bedeutet dieses Wort?', 'What does this word mean?', 'Plural Wörter (single words), Worte (words spoken, phrases).'),
  (10114, 'bedeuten', 'to mean', 'verb', null, null, 'A1', 191, 'communication', 'Was bedeutet dieses Wort?', 'What does this word mean?', 'Forms: bedeutet, bedeutete, hat bedeutet.'),
  (25, 'essen', 'to eat', 'verb', null, null, 'A1', 192, 'food', 'Wollen wir heute zusammen essen?', 'Shall we eat together today?', 'du isst, er isst.'),
  (10115, 'Essen', 'food, meal', 'noun', 'das', null, 'A1', 193, 'food', 'Das Essen in der Kantine ist gut.', 'The food in the canteen is good.', null),
  (10116, 'lieben', 'to love', 'verb', null, null, 'A1', 194, 'people', 'Ich liebe dich.', 'I love you.', 'For things/food usually lieben is strong mögen / gern is more everyday. Forms: liebt, liebte, hat geliebt.'),
  (10117, 'Polizei', 'police', 'noun', 'die', null, 'A1', 195, 'shopping', 'Rufen Sie die Polizei!', 'Call the police!', 'Emergency numbers: 110 police, 112 fire/ambulance.'),
  (62, 'schlecht', 'bad', 'adjective', null, null, 'A1', 196, 'everyday', 'Das Wetter ist heute schlecht.', 'The weather is bad today.', null),
  (10118, 'Platz', 'seat, square, space, place', 'noun', 'der', 'Plätze', 'A1', 197, 'everyday', 'Ist dieser Platz noch frei?', 'Is this seat still free?', null),
  (10119, 'vier', 'four', 'adjective', null, null, 'A1', 198, 'everyday', 'Wir sind vier Personen.', 'There are four of us.', null),
  (81, 'Abend', 'evening', 'noun', 'der', 'Abende', 'A1', 199, 'time', 'Am Abend sehe ich gern fern.', 'In the evening I like watching TV.', null),
  (10120, 'allein', 'alone, on one''s own', 'adverb', null, null, 'A1', 200, 'people', 'Ich wohne allein.', 'I live alone.', 'Also alleine in speech.'),
  (10121, 'holen', 'to fetch, to get', 'verb', null, null, 'A1', 201, 'everyday', 'Ich hole schnell Brot vom Bäcker.', 'I''ll quickly get some bread from the bakery.', 'Forms: holt, holte, hat geholt.'),
  (10122, 'weg', 'away, gone', 'adverb', null, null, 'A1', 202, 'everyday', 'Mein Fahrrad ist weg!', 'My bike is gone!', null),
  (10123, 'Weg', 'way, path, route', 'noun', 'der', 'Wege', 'A1', 203, 'everyday', 'Können Sie mir den Weg zum Bahnhof zeigen?', 'Can you show me the way to the station?', null),
  (10124, 'beginnen', 'to begin, to start', 'verb', null, null, 'A1', 204, 'time', 'Der Kurs beginnt um neun.', 'The course starts at nine.', 'Forms: beginnt, begann, hat begonnen.'),
  (10125, 'Moment', 'moment', 'noun', 'der', 'Momente', 'A1', 205, 'time', 'Einen Moment, bitte.', 'One moment, please.', null),
  (10126, 'Kopf', 'head', 'noun', 'der', 'Köpfe', 'A1', 206, 'people', 'Mir tut der Kopf weh.', 'My head hurts.', null),
