  (10325, 'Mittag', 'midday, noon', 'noun', 'der', 'Mittage', 'A1', 461, 'time', 'Wir essen zu Mittag in der Kantine.', 'We have lunch in the canteen.', 'zu Mittag essen = to have lunch.'),
  (10326, 'warm', 'warm', 'adjective', null, null, 'A1', 462, 'everyday', 'Heute ist es richtig warm.', 'It''s really warm today.', 'Warmmiete = rent including heating. Forms: wärmer, am wärmsten.'),
  (10327, 'Schrank', 'cupboard, wardrobe', 'noun', 'der', 'Schränke', 'A1', 463, 'home', 'Die Gläser sind im Schrank.', 'The glasses are in the cupboard.', null),
