  (10334, 'umziehen', 'to move (house), to change (clothes)', 'verb', null, null, 'A1', 472, 'home', 'Wir ziehen nächsten Monat um.', 'We''re moving next month.', 'sich umziehen = to get changed. Forms: zieht um, zog um, ist umgezogen.'),
  (10335, 'dunkel', 'dark', 'adjective', null, null, 'A1', 473, 'home', 'Im Winter wird es früh dunkel.', 'In winter it gets dark early.', 'Endings drop e: ein dunkles Zimmer.'),
  (10336, 'Lust', 'desire, feeling like (doing)', 'noun', 'die', null, 'A1', 474, 'people', 'Hast du Lust auf Kino?', 'Do you feel like going to the cinema?', 'Register: spoken. Lust haben auf + Akk / zu + infinitive.'),
