  (10349, 'Hobby', 'hobby', 'noun', 'das', 'Hobbys', 'A1', 492, 'travel', 'Was sind deine Hobbys?', 'What are your hobbies?', null),
  (10350, 'Balkon', 'balcony', 'noun', 'der', 'Balkone', 'A1', 493, 'home', 'Die Wohnung hat einen schönen Balkon.', 'The flat has a lovely balcony.', 'Plural also Balkons.'),
  (60, 'aufstehen', 'to get up', 'verb', null, null, 'A1', 494, 'everyday', 'Ich muss morgen früh aufstehen.', 'I have to get up early tomorrow.', 'Separable: Ich stehe um sechs auf.'),
  (10351, 'Geschwister', 'siblings', 'noun', 'die', null, 'A1', 495, 'people', 'Ich habe keine Geschwister.', 'I don''t have any siblings.', 'Plural only.'),
  (10352, 'regnen', 'to rain', 'verb', null, null, 'A1', 496, 'everyday', 'Es regnet schon den ganzen Tag.', 'It''s been raining all day.', 'Only with es. Forms: regnet, regnete, hat geregnet.'),
