  (10421, 'null', 'zero', 'adjective', null, null, 'A1', 578, 'everyday', 'Die Vorwahl beginnt mit null.', 'The area code starts with zero.', null),
  (85, 'Abendessen', 'dinner, evening meal', 'noun', 'das', 'Abendessen', 'A1', 579, 'food', 'Was gibt es heute zum Abendessen?', 'What''s for dinner tonight?', null),
  (10422, 'nächste', 'next, nearest', 'adjective', null, null, 'A1', 580, 'time', 'Wann fährt der nächste Bus?', 'When does the next bus leave?', 'Superlative of nah. nächste Woche = next week.'),
  (10423, 'Nachname', 'surname, last name', 'noun', 'der', 'Nachnamen', 'A1', 581, 'people', 'Können Sie Ihren Nachnamen buchstabieren?', 'Could you spell your surname?', 'Formal: der Familienname.'),
  (10424, 'Uhrzeit', 'time (of day)', 'noun', 'die', 'Uhrzeiten', 'A1', 582, 'time', 'Um welche Uhrzeit beginnt der Kurs?', 'What time does the course start?', null),
  (10425, 'erste, zweite, dritte', 'first, second, third', 'adjective', null, null, 'A1', 583, 'everyday', 'Ich wohne im dritten Stock.', 'I live on the third floor.', 'Ordinals: -te up to 19 (vierte, siebte), -ste from 20 (zwanzigste). Dates: am ersten Mai.'),
  (112, 'später', 'later', 'adverb', null, null, 'A1', 584, 'time', 'Ich rufe dich später an.', 'I''ll call you later.', null),
  (10426, 'alles', 'everything', 'pronoun', null, null, 'A1', 585, 'communication', 'Ist alles in Ordnung?', 'Is everything all right?', null),
  (10427, 'letzte', 'last, previous', 'adjective', null, null, 'A1', 586, 'time', 'Letzte Woche war ich krank.', 'Last week I was ill.', null),
  (18, 'Danke', 'thank you, thanks', 'phrase', null, null, 'A1', 587, 'communication', 'Danke für deine Hilfe!', 'Thanks for your help!', null),
  (19, 'Bitte', 'please; you''re welcome', 'phrase', null, null, 'A1', 588, 'communication', 'Ein Wasser, bitte.', 'A water, please.', null),
  (20, 'Entschuldigung', 'excuse me; sorry', 'phrase', null, null, 'A1', 589, 'communication', 'Entschuldigung, wo ist der Bahnhof?', 'Excuse me, where is the train station?', null),
  (43, 'mit', 'with', 'preposition', null, null, 'A1', 590, 'everyday', 'Ich fahre mit dem Bus zur Arbeit.', 'I take the bus to work.', 'mit + Dativ: mit dem Bus, mit der Bahn.'),
  (47, 'Wie geht''s?', 'how are you?', 'phrase', null, null, 'A1', 591, 'communication', 'Hallo Anna, wie geht''s?', 'Hi Anna, how are you?', 'Formal: Wie geht es Ihnen?'),
  (69, 'Tschüss', 'bye', 'phrase', null, null, 'A1', 592, 'communication', 'Tschüss, bis morgen!', 'Bye, see you tomorrow!', null),
  (79, 'E-Mail', 'email', 'noun', 'die', 'E-Mails', 'A1', 593, 'communication', 'Ich schreibe dir später eine E-Mail.', 'I''ll write you an email later.', null),
  (128, 'für', 'for', 'preposition', null, null, 'A1', 594, 'everyday', 'Das Geschenk ist für dich.', 'The present is for you.', 'für + Akkusativ: für dich, für meinen Bruder.'),
  (129, 'nach', 'after; to (cities, countries, home)', 'preposition', null, null, 'A1', 595, 'time', 'Nach der Arbeit gehe ich einkaufen.', 'After work I''m going shopping.', 'nach + Dativ. nach Berlin, nach Hause.'),
  (130, 'bei', 'at (someone''s place or company)', 'preposition', null, null, 'A1', 596, 'people', 'Ich bin heute Abend bei meinen Eltern.', 'I''m at my parents'' this evening.', 'bei + Dativ: beim Arzt = bei dem Arzt.'),
  (131, 'zu', 'to (a person or place)', 'preposition', null, null, 'A1', 597, 'everyday', 'Ich gehe morgen zu meiner Oma.', 'I''m going to my grandma''s tomorrow.', 'zu + Dativ: zum = zu dem, zur = zu der.'),
  (132, 'aus', 'from (origin), out of', 'preposition', null, null, 'A1', 598, 'people', 'Ich komme aus Polen.', 'I''m from Poland.', 'aus + Dativ.'),
  (133, 'von', 'from (a person or starting point); of', 'preposition', null, null, 'A1', 599, 'everyday', 'Das ist ein Geschenk von meiner Mutter.', 'That''s a present from my mother.', 'von + Dativ: vom = von dem.'),
  (136, 'Guten Morgen', 'good morning', 'phrase', null, null, 'A1', 600, 'communication', 'Guten Morgen! Hast du gut geschlafen?', 'Good morning! Did you sleep well?', null),
  (137, 'Bis später', 'see you later', 'phrase', null, null, 'A1', 601, 'communication', 'Ich muss los. Bis später!', 'I have to go. See you later!', null),
  (138, 'Keine Ahnung', 'no idea', 'phrase', null, null, 'A1', 602, 'communication', 'Wo ist Tom? – Keine Ahnung.', 'Where''s Tom? – No idea.', null),
  (139, 'Wie bitte?', 'pardon? (I didn''t catch that)', 'phrase', null, null, 'A1', 603, 'communication', 'Wie bitte? Können Sie das wiederholen?', 'Pardon? Could you repeat that?', null),
  (140, 'Kein Problem', 'no problem', 'phrase', null, null, 'A1', 604, 'communication', 'Danke! – Kein Problem.', 'Thanks! – No problem.', null),
  (141, 'Guten Appetit', 'enjoy your meal', 'phrase', null, null, 'A1', 605, 'food', 'Das Essen ist fertig. Guten Appetit!', 'Dinner''s ready. Enjoy your meal!', null),
  (142, 'Ich hätte gern', 'I''d like (when ordering)', 'phrase', null, null, 'A1', 606, 'shopping', 'Ich hätte gern ein Stück Kuchen.', 'I''d like a piece of cake.', null),
  (143, 'Alles klar', 'all right, got it', 'phrase', null, null, 'A1', 607, 'communication', 'Alles klar, bis morgen!', 'All right, see you tomorrow!', null),
  (1081, 'Gute Besserung', 'get well soon', 'phrase', null, null, 'A1', 608, 'appointments', 'Du bist krank? Gute Besserung!', 'You''re ill? Get well soon!', null),
  (1082, 'Es tut mir leid', 'I''m sorry', 'phrase', null, null, 'A1', 609, 'communication', 'Es tut mir leid, ich bin zu spät.', 'I''m sorry, I''m late.', null),
  (1084, 'Viel Glück', 'good luck', 'phrase', null, null, 'A1', 610, 'communication', 'Viel Glück bei der Prüfung!', 'Good luck in the exam!', null),
  (10428, 'der, die, das', 'the', 'pronoun', null, null, 'A1', 611, 'communication', 'Der Bus ist heute voll, die Bahn ist leer.', 'The bus is full today, the train is empty.', 'Definite article. der (m), die (f), das (n), die (plural) changes with case: den, dem, des.'),
  (10429, 'ein, eine', 'a, an, one', 'pronoun', null, null, 'A1', 612, 'communication', 'Ich hätte gern einen Kaffee und ein Wasser.', 'I''d like a coffee and a water.', 'Indefinite article: ein (m/n), eine (f) accusative masculine einen. No plural.'),
  (10430, 'alle', 'all, everyone', 'pronoun', null, null, 'A1', 613, 'communication', 'Alle sind schon da.', 'Everyone is already here.', 'alle (plural) = all, everyone alles = everything.'),
  (10431, 'andere', 'other, different', 'pronoun', null, null, 'A1', 614, 'communication', 'Haben Sie das auch in einer anderen Farbe?', 'Do you have that in another colour too?', 'Adjective endings: der andere, ein anderer.'),
  (10432, 'etwas', 'something, somewhat, a little', 'pronoun', null, null, 'A1', 615, 'communication', 'Möchtest du etwas trinken?', 'Would you like something to drink?', 'etwas = something also ''a bit'' before adjectives (etwas teuer).'),
  (10433, 'jemand', 'someone, anyone', 'pronoun', null, null, 'A1', 616, 'people', 'Hat jemand meinen Schlüssel gesehen?', 'Has anyone seen my key?', null),
  (10434, 'sich', 'oneself, himself, herself, themselves, each other', 'pronoun', null, null, 'A1', 617, 'communication', 'Die beiden kennen sich schon lange.', 'The two have known each other for a long time.', 'Reflexive pronoun for er/sie/es/sie/Sie: sich freuen, sich treffen.'),
  (10435, 'in', 'in, into', 'preposition', null, null, 'A1', 618, 'communication', 'Ich wohne in Hamburg.', 'I live in Hamburg.', 'Two-way preposition: wo? + Dat (im Kino), wohin? + Akk (ins Kino). im = in dem, ins = in das.'),
  (10436, 'an', 'at, on, to', 'preposition', null, null, 'A1', 619, 'communication', 'Das Bild hängt an der Wand.', 'The picture is hanging on the wall.', 'Two-way preposition. Time: am Montag, am Abend. am = an dem.'),
  (10437, 'auf', 'on, onto, at', 'preposition', null, null, 'A1', 620, 'communication', 'Das Handy liegt auf dem Tisch.', 'The phone is on the table.', 'Two-way preposition. Also: auf Deutsch, auf Wiedersehen.'),
  (10438, 'über', 'over, above, about, via', 'preposition', null, null, 'A1', 621, 'communication', 'Wir sprechen morgen über das Projekt.', 'We''ll talk about the project tomorrow.', 'Two-way preposition. über + Akk = about (a topic).'),
  (10439, 'unter', 'under, below, among', 'preposition', null, null, 'A1', 622, 'communication', 'Die Katze schläft unter dem Bett.', 'The cat is sleeping under the bed.', 'Two-way preposition.'),
  (10440, 'vor', 'in front of, before, ago', 'preposition', null, null, 'A1', 623, 'communication', 'Ich warte vor dem Kino auf dich.', 'I''ll wait for you in front of the cinema.', 'Two-way preposition. Time + Dat: vor einer Woche = a week ago.'),
  (10441, 'gegen', 'against, around (time)', 'preposition', null, null, 'A1', 624, 'communication', 'Ich komme gegen acht Uhr.', 'I''ll come at around eight.', 'Always + Akkusativ.'),
  (10442, 'um', 'at (clock time), around', 'preposition', null, null, 'A1', 625, 'communication', 'Der Kurs beginnt um neun Uhr.', 'The course starts at nine.', 'Always + Akkusativ. um ... zu = in order to.'),
  (10443, 'lieber', 'rather, preferably', 'adverb', null, null, 'A1', 626, 'communication', 'Ich trinke lieber Tee.', 'I''d rather have tea.', 'Comparative of gern. am liebsten = most of all.'),
  (10444, 'besetzt', 'occupied, taken, engaged (phone)', 'adjective', null, null, 'A1', 627, 'everyday', 'Die Toilette ist besetzt.', 'The toilet is occupied.', null),
  (10445, 'U-Bahn', 'underground, subway', 'noun', 'die', 'U-Bahnen', 'A1', 628, 'transport', 'Die U-Bahn fährt alle fünf Minuten.', 'The underground runs every five minutes.', null),
  (10446, 'Hallo', 'hello, hi', 'phrase', null, null, 'A1', 629, 'people', 'Hallo, wie geht''s?', 'Hi, how are you?', 'Register: spoken. Informal also fine in many workplaces.'),
  (10447, 'Guten Tag', 'good day, hello', 'phrase', null, null, 'A1', 630, 'people', 'Guten Tag, ich habe einen Termin um zehn.', 'Hello, I have an appointment at ten.', 'Register: formal. Neutral-formal greeting in shops and offices during the day.'),
  (10448, 'Guten Abend', 'good evening', 'phrase', null, null, 'A1', 631, 'people', 'Guten Abend, einen Tisch für zwei, bitte.', 'Good evening, a table for two, please.', null),
  (10449, 'Gute Nacht', 'good night', 'phrase', null, null, 'A1', 632, 'people', 'Gute Nacht, schlaf gut!', 'Good night, sleep well!', 'Only when going to bed or leaving late at night.'),
  (10450, 'Auf Wiedersehen', 'goodbye', 'phrase', null, null, 'A1', 633, 'people', 'Auf Wiedersehen und einen schönen Tag noch!', 'Goodbye and have a nice day!', 'Register: formal. Formal goodbye. On the phone: Auf Wiederhören.'),
  (10452, 'Mir geht''s gut', 'I''m fine, I''m well', 'phrase', null, null, 'A1', 634, 'people', 'Danke, mir geht''s gut. Und dir?', 'Thanks, I''m fine. And you?', 'Register: spoken. Dativ: mir geht es gut / schlecht.'),
  (10453, 'Freut mich', 'nice to meet you', 'phrase', null, null, 'A1', 635, 'people', 'Ich bin Tom. – Freut mich, Anna.', 'I''m Tom. – Nice to meet you, I''m Anna.', 'Longer: Freut mich, Sie kennenzulernen.'),
  (10454, 'Vielen Dank', 'thank you very much', 'phrase', null, null, 'A1', 636, 'people', 'Vielen Dank für die Einladung!', 'Thank you very much for the invitation!', null),
  (10455, 'Gern geschehen', 'you''re welcome', 'phrase', null, null, 'A1', 637, 'people', 'Danke! – Gern geschehen.', 'Thanks! – You''re welcome.', 'Shorter: Gern!'),
  (10456, 'Können Sie das bitte wiederholen?', 'could you repeat that, please?', 'phrase', null, null, 'A1', 638, 'communication', 'Entschuldigung, können Sie das bitte wiederholen?', 'Sorry, could you repeat that, please?', 'Register: formal. Informal: Kannst du das noch mal sagen?'),
  (10457, 'Was bedeutet das?', 'what does that mean?', 'phrase', null, null, 'A1', 639, 'communication', 'Was bedeutet das Wort „Anmeldung“?', 'What does the word ''Anmeldung'' mean?', 'Also: Was heißt das?'),
  (10458, 'Wie sagt man das auf Deutsch?', 'how do you say that in German?', 'phrase', null, null, 'A1', 640, 'communication', 'Wie sagt man das auf Deutsch?', 'How do you say that in German?', null),
  (10459, 'Wie schreibt man das?', 'how do you spell/write that?', 'phrase', null, null, 'A1', 641, 'communication', 'Wie schreibt man Ihren Namen?', 'How do you spell your name?', null),
  (10460, 'Sprechen Sie Englisch?', 'do you speak English?', 'phrase', null, null, 'A1', 642, 'communication', 'Entschuldigung, sprechen Sie Englisch?', 'Excuse me, do you speak English?', null),
  (10461, 'Wie spät ist es?', 'what time is it?', 'phrase', null, null, 'A1', 643, 'time', 'Entschuldigung, wie spät ist es?', 'Excuse me, what time is it?', 'Also: Wie viel Uhr ist es?'),
  (10462, 'Was ist los?', 'what''s the matter? what''s going on?', 'phrase', null, null, 'A1', 644, 'people', 'Du siehst müde aus. Was ist los?', 'You look tired. What''s wrong?', 'Register: spoken.'),
  (10463, 'Klar', 'sure, of course', 'phrase', null, null, 'A1', 645, 'communication', 'Kannst du mir helfen? – Klar!', 'Can you help me? – Sure!', 'Register: spoken. As adjective: clear (Das ist klar).'),
  (10464, 'Ich weiß nicht', 'I don''t know', 'phrase', null, null, 'A1', 646, 'communication', 'Ich weiß nicht, wann der Bus kommt.', 'I don''t know when the bus is coming.', 'Very frequent in speech often shortened to Weiß nicht.'),
  (10465, 'Ach so', 'oh, I see', 'phrase', null, null, 'A1', 647, 'communication', 'Ach so, jetzt verstehe ich.', 'Oh, I see, now I understand.', 'Register: spoken.'),
  (10466, 'Schade', 'what a pity, too bad', 'phrase', null, null, 'A1', 648, 'people', 'Du kannst nicht kommen? Schade!', 'You can''t come? What a pity!', null),
  (10467, 'Gute Idee', 'good idea', 'phrase', null, null, 'A1', 649, 'communication', 'Wollen wir ins Kino gehen? – Gute Idee!', 'Shall we go to the cinema? – Good idea!', null),
  (10468, 'Echt?', 'really?', 'phrase', null, null, 'A1', 650, 'communication', 'Echt? Das wusste ich nicht.', 'Really? I didn''t know that.', 'Register: spoken, informal. echt = really (Das ist echt gut). Neutral: Wirklich?'),
  (10470, 'Zusammen oder getrennt?', 'together or separately? (paying)', 'phrase', null, null, 'A1', 651, 'food', 'Zusammen oder getrennt? – Getrennt, bitte.', 'Together or separately? – Separately, please.', 'Standard question from waiters in Germany.'),
  (10471, 'Stimmt so', 'keep the change', 'phrase', null, null, 'A1', 652, 'food', 'Das macht 18 Euro. – Hier sind 20, stimmt so.', 'That''s 18 euros. – Here''s 20, keep the change.', 'Register: spoken. How to leave a tip when paying.'),
  (10472, 'Sonst noch etwas?', 'anything else?', 'phrase', null, null, 'A1', 653, 'shopping', 'Sonst noch etwas? – Nein, danke, das war''s.', 'Anything else? – No, thanks, that''s all.', 'Spoken: Sonst noch was?'),
  (10473, 'Das war''s', 'that''s all, that''s it', 'phrase', null, null, 'A1', 654, 'shopping', 'Nein, danke, das war''s.', 'No, thanks, that''s all.', 'Register: spoken.'),
  (10474, 'Zum Mitnehmen', 'to take away, to go', 'phrase', null, null, 'A1', 655, 'food', 'Einen Kaffee zum Mitnehmen, bitte.', 'A coffee to go, please.', 'Question: Zum Hieressen oder zum Mitnehmen?'),
  (10476, 'Gesundheit', 'bless you (after a sneeze)', 'phrase', null, null, 'A1', 656, 'people', 'Hatschi! – Gesundheit!', 'Atchoo! – Bless you!', 'As a noun: health.'),
  (10477, 'Alles Gute', 'all the best', 'phrase', null, null, 'A1', 657, 'people', 'Alles Gute zum Geburtstag!', 'Happy birthday!', null),
  (10478, 'Herzlichen Glückwunsch', 'congratulations', 'phrase', null, null, 'A1', 658, 'people', 'Herzlichen Glückwunsch zur neuen Stelle!', 'Congratulations on the new job!', 'zu + Dat: zum Geburtstag, zur Hochzeit.'),
  (10479, 'Viel Spaß', 'have fun', 'phrase', null, null, 'A1', 659, 'people', 'Viel Spaß im Urlaub!', 'Have fun on holiday!', null),
  (10480, 'Schönes Wochenende', 'have a nice weekend', 'phrase', null, null, 'A1', 660, 'people', 'Tschüss und schönes Wochenende!', 'Bye and have a nice weekend!', 'Pattern: Schönen Tag noch! Schönen Abend!'),
  (10481, 'Wie komme ich zum Bahnhof?', 'how do I get to the station?', 'phrase', null, null, 'A1', 661, 'transport', 'Entschuldigung, wie komme ich zum Bahnhof?', 'Excuse me, how do I get to the station?', 'Pattern: Wie komme ich zum/zur ...?'),
  (10482, 'ein paar', 'a few, a couple of', 'pronoun', null, null, 'A1', 662, 'communication', 'Ich habe noch ein paar Fragen.', 'I have a few more questions.', 'Lower case paar = a few das Paar = a pair/couple.'),
  (10561, 'sich kennen', 'to know each other', 'verb', null, null, 'A1', 663, 'people', 'Woher kennt ihr euch?', 'How do you two know each other?', 'Forms: kennt sich, kannte sich, hat sich gekannt.'),
  (10562, 'Ort', 'place, village', 'noun', 'der', 'Orte', 'A1', 664, 'everyday', 'Wir suchen einen ruhigen Ort für das Treffen.', 'We''re looking for a quiet place for the meeting.', 'vor Ort = on site.'),
  (10563, 'warten auf', 'to wait for', 'verb', null, null, 'A1', 665, 'everyday', 'Ich warte auf den Bus.', 'I''m waiting for the bus.', 'Not *warten für*. Forms: wartet, wartete, hat gewartet.'),
  (10564, 'lieb', 'kind, sweet, dear', 'adjective', null, null, 'A1', 666, 'people', 'Das ist lieb von dir.', 'That''s kind of you.', 'Lieber Tom / Liebe Anna = Dear (informal letters).'),
  (10565, 'sich treffen mit', 'to meet up with', 'verb', null, null, 'A1', 667, 'people', 'Ich treffe mich heute mit Freunden.', 'I''m meeting up with friends today.', 'Forms: trifft sich, traf sich, hat sich getroffen.'),
  (10566, 'bekannt', 'well-known, familiar', 'adjective', null, null, 'A1', 668, 'people', 'Das Restaurant ist sehr bekannt.', 'The restaurant is very well known.', 'bekannt mit = acquainted with.'),
  (10567, 'Stelle', 'position, job, place', 'noun', 'die', 'Stellen', 'A1', 669, 'work', 'Ich habe eine neue Stelle gefunden.', 'I''ve found a new job.', 'Stellenanzeige = job advert. an deiner Stelle = in your place.'),
  (10568, 'Raum', 'space, room, area', 'noun', 'der', 'Räume', 'A1', 670, 'everyday', 'Die Besprechung ist in Raum 204.', 'The meeting is in room 204.', null),
  (10569, 'Thema', 'topic, subject', 'noun', 'das', 'Themen', 'A1', 671, 'communication', 'Das ist ein wichtiges Thema.', 'That''s an important topic.', null),
  (10570, 'Klasse', 'class, year (school), great (spoken)', 'noun', 'die', 'Klassen', 'A1', 672, 'work', 'Mein Sohn ist in der dritten Klasse.', 'My son is in Year 3.', 'Spoken: Klasse! = Great!'),
  (10571, 'Blick', 'view, look, glance', 'noun', 'der', 'Blicke', 'A1', 673, 'everyday', 'Das Zimmer hat einen schönen Blick auf den See.', 'The room has a lovely view of the lake.', 'auf den ersten Blick = at first glance.'),
  (10572, 'verdienen', 'to earn, to deserve', 'verb', null, null, 'A1', 674, 'shopping', 'Er verdient nicht schlecht.', 'He earns quite well.', 'Forms: verdient, verdiente, hat verdient.'),
  (10573, 'Gruppe', 'group', 'noun', 'die', 'Gruppen', 'A1', 675, 'people', 'Wir arbeiten in kleinen Gruppen.', 'We work in small groups.', null),
  (10574, 'Gast', 'guest', 'noun', 'der', 'Gäste', 'A1', 676, 'people', 'Wir haben heute Abend Gäste.', 'We have guests tonight.', null),
  (10575, 'Kunde', 'customer, client', 'noun', 'der', 'Kunden', 'A1', 677, 'shopping', 'Der Kunde möchte mit dem Chef sprechen.', 'The customer wants to speak to the manager.', 'n-declension. Female: die Kundin.'),
  (10576, 'zu Fuß gehen', 'to walk, to go on foot', 'verb', null, null, 'A1', 678, 'transport', 'Wir gehen zu Fuß, es ist nicht weit.', 'We''ll walk, it isn''t far.', null),
  (10577, 'Gespräch', 'conversation, talk', 'noun', 'das', 'Gespräche', 'A1', 679, 'communication', 'Das war ein gutes Gespräch.', 'That was a good conversation.', null),
  (10578, 'Feuer', 'fire', 'noun', 'das', 'Feuer', 'A1', 680, 'everyday', 'Im Notfall: Feuer – 112.', 'In an emergency: fire – 112.', 'Feuerwehr = fire brigade.'),
  (10579, 'Ergebnis', 'result', 'noun', 'das', 'Ergebnisse', 'A1', 681, 'work', 'Das Ergebnis bekommen Sie nächste Woche.', 'You''ll get the result next week.', null),
  (10580, 'Test', 'test', 'noun', 'der', 'Tests', 'A1', 682, 'work', 'Der Test war ganz einfach.', 'The test was really easy.', null),
  (10581, 'enden', 'to end, to finish', 'verb', null, null, 'A1', 683, 'time', 'Der Kurs endet im Juni.', 'The course ends in June.', 'Forms: endet, endete, hat geendet.'),
  (10582, 'Schluss', 'conclusion, end', 'noun', 'der', 'Schlüsse', 'A1', 684, 'time', 'Zum Schluss möchte ich mich bedanken.', 'Finally, I''d like to say thank you.', 'Schluss machen = to break up / to call it a day.'),
  (10583, 'Baum', 'tree', 'noun', 'der', 'Bäume', 'A1', 685, 'everyday', 'Vor dem Haus steht ein großer Baum.', 'There''s a big tree in front of the house.', null),
  (10584, 'Haar', 'hair', 'noun', 'das', 'Haare', 'A1', 686, 'people', 'Sie hat kurze Haare.', 'She has short hair.', 'Usually plural for hair on the head.'),
  (1033, 'Lösung', 'solution', 'noun', 'die', 'Lösungen', 'A1', 687, 'work', 'Wir finden bestimmt eine Lösung.', 'I''m sure we''ll find a solution.', null),
  (10585, 'Dame', 'lady', 'noun', 'die', 'Damen', 'A1', 688, 'people', 'Meine Damen und Herren, willkommen!', 'Ladies and gentlemen, welcome!', 'Register: formal. Signs: Damen / Herren = women / men (toilets).'),
  (10586, 'Zeitung', 'newspaper', 'noun', 'die', 'Zeitungen', 'A1', 689, 'communication', 'Ich lese die Zeitung online.', 'I read the newspaper online.', null),
  (10587, 'heiraten', 'to marry, to get married', 'verb', null, null, 'A1', 690, 'people', 'Wir heiraten im Mai.', 'We''re getting married in May.', '+Akk: Er heiratet seine Freundin. Forms: heiratet, heiratete, hat geheiratet.'),
  (10588, 'Mund', 'mouth', 'noun', 'der', 'Münder', 'A1', 691, 'people', 'Bitte machen Sie den Mund auf.', 'Please open your mouth.', null),
  (10589, 'böse', 'angry, bad, evil', 'adjective', null, null, 'A1', 692, 'people', 'Sei mir bitte nicht böse.', 'Please don''t be angry with me.', 'böse sein + Dat = to be angry with someone.'),
  (10590, 'Maschine', 'machine', 'noun', 'die', 'Maschinen', 'A1', 693, 'work', 'Die Maschine läuft wieder.', 'The machine is running again.', null),
  (10591, 'tanzen', 'to dance', 'verb', null, null, 'A1', 694, 'travel', 'Gehen wir am Samstag tanzen?', 'Shall we go dancing on Saturday?', 'Forms: tanzt, tanzte, hat getanzt.'),
