  (10717, 'abfliegen', 'to take off, to depart (flight)', 'verb', null, null, 'A1', 814, 'travel', 'Wir fliegen um sieben Uhr ab.', 'We take off at seven.', 'Forms: fliegt ab, flog ab, ist abgeflogen.'),
  (10719, 'Einzelzimmer', 'single room', 'noun', 'das', 'Einzelzimmer', 'A1', 815, 'travel', 'Ein Einzelzimmer kostet 80 Euro pro Nacht.', 'A single room costs 80 euros a night.', null),
