  (10722, 'Wochentag', 'weekday, day of the week', 'noun', 'der', 'Wochentage', 'A1', 817, 'time', 'An Wochentagen fährt der Bus alle zehn Minuten.', 'On weekdays the bus runs every ten minutes.', 'Weekday adverbs: montags, dienstags ... = on Mondays, Tuesdays.'),
  (10724, 'Doppelzimmer', 'double room', 'noun', 'das', 'Doppelzimmer', 'A1', 818, 'travel', 'Haben Sie noch ein Doppelzimmer frei?', 'Do you still have a double room available?', null),
  (10725, 'ankreuzen', 'to tick, to mark with a cross', 'verb', null, null, 'A1', 819, 'appointments', 'Bitte kreuzen Sie das Richtige an.', 'Please tick the right answer.', 'Forms: kreuzt an, kreuzte an, hat angekreuzt.'),
  (10726, 'Wohnort', 'place of residence', 'noun', 'der', 'Wohnorte', 'A1', 820, 'appointments', 'Name, Alter und Wohnort, bitte.', 'Name, age and place of residence, please.', null),
