  (11245, 'Hausarzt', 'GP, family doctor', 'noun', 'der', 'Hausärzte', 'A2', 550, 'appointments', 'Ich gehe zuerst zum Hausarzt.', 'I''ll go to my GP first.', 'Female: die Hausärztin. The GP usually refers you to specialists.'),
  (11246, 'Vollzeit', 'full-time', 'noun', 'die', null, 'A2', 551, 'work', 'Ich arbeite Vollzeit.', 'I work full-time.', null),
