  (11261, 'Sehr geehrte Damen und Herren', 'Dear Sir or Madam', 'phrase', null, null, 'A2', 566, 'appointments', 'Sehr geehrte Damen und Herren, ich schreibe Ihnen wegen ...', 'Dear Sir or Madam, I''m writing to you about ...', 'Register: formal, written. Formal letter opening Sehr geehrte Frau Weber / Sehr geehrter Herr Weber.'),
  (11262, 'Mit freundlichen Grüßen', 'kind regards, yours sincerely', 'phrase', null, null, 'A2', 567, 'appointments', 'Vielen Dank im Voraus. Mit freundlichen Grüßen, Anna Nowak.', 'Thank you in advance. Kind regards, Anna Nowak.', 'Register: formal, written. Standard formal closing. Less formal: Viele Grüße.'),
  (11263, 'IBAN', 'IBAN (bank account number)', 'noun', 'die', 'IBANs', 'A2', 568, 'shopping', 'Können Sie mir Ihre IBAN schicken?', 'Can you send me your IBAN?', null),
