  (11291, 'Ich finde, dass ...', 'I think that ...', 'phrase', null, null, 'A2', 594, 'communication', 'Ich finde, dass die Miete zu hoch ist.', 'I think the rent is too high.', 'dass sends the verb to the end. Without dass: Ich finde, die Miete ist zu hoch.'),
  (11292, 'Meiner Meinung nach', 'in my opinion', 'phrase', null, null, 'A2', 595, 'communication', 'Meiner Meinung nach ist das zu teuer.', 'In my opinion that''s too expensive.', 'Verb follows directly: Meiner Meinung nach ist ...'),
  (11293, 'Das sehe ich auch so', 'I see it the same way', 'phrase', null, null, 'A2', 596, 'communication', 'Das sehe ich auch so.', 'I see it the same way.', 'Agreement. Disagreement: Das sehe ich anders.'),
  (11294, 'Das sehe ich anders', 'I see it differently', 'phrase', null, null, 'A2', 597, 'communication', 'Das sehe ich anders.', 'I see that differently.', 'Polite disagreement.'),
