  (11300, 'Würden Sie ...?', 'would you ...?', 'phrase', null, null, 'A2', 603, 'communication', 'Würden Sie bitte das Fenster schließen?', 'Would you close the window, please?', 'Register: formal. Polite request: würden + infinitive at the end.'),
  (11301, 'Was meinen Sie damit?', 'what do you mean by that?', 'phrase', null, null, 'A2', 604, 'communication', 'Was meinen Sie damit?', 'What do you mean by that?', 'Informal: Was meinst du damit?'),
  (11302, 'Wie meinst du das?', 'what do you mean?', 'phrase', null, null, 'A2', 605, 'communication', 'Wie meinst du das?', 'What do you mean?', 'Register: spoken.'),
