  (11307, 'Ich schaue nur', 'I''m just looking', 'phrase', null, null, 'A2', 608, 'shopping', 'Danke, ich schaue nur.', 'Thanks, I''m just looking.', 'Also: Ich schaue mich nur um.'),
  (11308, 'Haben Sie das auch in ...?', 'do you have this in ...? (size/colour)', 'phrase', null, null, 'A2', 609, 'shopping', 'Haben Sie das auch in Größe 40?', 'Do you have this in size 40 too?', null),
  (11309, 'Wo finde ich ...?', 'where can I find ...?', 'phrase', null, null, 'A2', 610, 'shopping', 'Entschuldigung, wo finde ich die Milch?', 'Excuse me, where can I find the milk?', null),
