  (11311, 'Geht es auch am ...?', 'is ... possible too? (date/time)', 'phrase', null, null, 'A2', 612, 'appointments', 'Geht es auch am Donnerstag?', 'Is Thursday possible too?', null),
  (11312, 'Ich rufe wegen ... an', 'I''m calling about ...', 'phrase', null, null, 'A2', 613, 'communication', 'Guten Tag, ich rufe wegen des Termins an.', 'Hello, I''m calling about the appointment.', 'wegen + Genitiv (spoken often Dativ).'),
  (11313, 'Kann ich eine Nachricht hinterlassen?', 'can I leave a message?', 'phrase', null, null, 'A2', 614, 'communication', 'Herr Weber ist nicht da? Kann ich eine Nachricht hinterlassen?', 'Mr Weber isn''t in? Can I leave a message?', null),
  (11316, 'Hast du Lust, ...?', 'do you fancy ...? / would you like to ...?', 'phrase', null, null, 'A2', 615, 'people', 'Hast du Lust, heute Abend ins Kino zu gehen?', 'Do you fancy going to the cinema tonight?', 'Lust haben + zu + infinitive / auf + Akk.'),
  (11317, 'Hast du am Wochenende schon was vor?', 'have you got any plans for the weekend?', 'phrase', null, null, 'A2', 616, 'people', 'Hast du am Wochenende schon was vor?', 'Have you got anything planned for the weekend?', 'Register: spoken.'),
  (11318, 'Leider kann ich nicht', 'unfortunately I can''t', 'phrase', null, null, 'A2', 617, 'people', 'Leider kann ich am Freitag nicht.', 'Unfortunately I can''t on Friday.', 'Polite refusal often + Vielleicht ein andermal?'),
  (11319, 'Ein anderes Mal', 'another time', 'phrase', null, null, 'A2', 618, 'people', 'Heute geht es nicht, vielleicht ein anderes Mal?', 'Today''s no good, maybe another time?', 'Spoken: ein andermal.'),
  (11320, 'Gern, warum nicht?', 'why not?, sure', 'phrase', null, null, 'A2', 619, 'people', 'Kommst du mit? – Gern, warum nicht?', 'Are you coming? – Sure, why not?', 'Register: spoken.'),
  (11321, 'Ich glaube schon', 'I think so', 'phrase', null, null, 'A2', 620, 'communication', 'Kommt er auch? – Ich glaube schon.', 'Is he coming too? – I think so.', 'Register: spoken. Negative: Ich glaube nicht.'),
  (11322, 'Ich glaube nicht', 'I don''t think so', 'phrase', null, null, 'A2', 621, 'communication', 'Ist der Laden noch offen? – Ich glaube nicht.', 'Is the shop still open? – I don''t think so.', 'Register: spoken.'),
  (11323, 'Wie war''s?', 'how was it?', 'phrase', null, null, 'A2', 622, 'people', 'Na, wie war''s im Urlaub?', 'So, how was the holiday?', 'Register: spoken.'),
  (11324, 'Es geht', 'it''s OK, so-so', 'phrase', null, null, 'A2', 623, 'people', 'Wie war der Film? – Es geht.', 'How was the film? – It was OK.', 'Register: spoken. Lukewarm answer.'),
  (11325, 'Was ist passiert?', 'what happened?', 'phrase', null, null, 'A2', 624, 'communication', 'Du siehst traurig aus. Was ist passiert?', 'You look sad. What happened?', null),
