  (11328, 'Ist das richtig so?', 'is this right?', 'phrase', null, null, 'A2', 627, 'communication', 'Ich habe das Formular ausgefüllt. Ist das richtig so?', 'I''ve filled in the form. Is this right?', null),
  (11329, 'Was brauche ich dafür?', 'what do I need for that?', 'phrase', null, null, 'A2', 628, 'appointments', 'Ich möchte mich anmelden. Was brauche ich dafür?', 'I''d like to register. What do I need for that?', null),
  (11330, 'Bis wann?', 'by when? until when?', 'phrase', null, null, 'A2', 629, 'time', 'Bis wann muss ich das abgeben?', 'By when do I have to hand that in?', null),
  (11331, 'Ab wann?', 'from when?', 'phrase', null, null, 'A2', 630, 'time', 'Ab wann ist die Wohnung frei?', 'From when is the flat available?', null),
