  (12916, 'z. B.', 'e.g.', 'adverb', null, null, 'A2', 769, 'communication', 'Obst, z. B. Äpfel und Birnen.', 'Fruit, e.g. apples and pears.', 'Register: written. Read: zum Beispiel. Mainly to understand when reading or listening.'),
  (12917, 'usw.', 'etc.', 'adverb', null, null, 'A2', 770, 'communication', 'Brot, Milch, Käse usw.', 'Bread, milk, cheese, etc.', 'Register: written. Read: und so weiter. Mainly to understand when reading or listening.'),
  (10560, 'nachdem', 'after', 'conjunction', null, null, 'B1', 1, 'communication', 'Nachdem ich gegessen hatte, bin ich ins Bett gegangen.', 'After I had eaten, I went to bed.', 'Verb to the end often with Plusquamperfekt. Preposition = nach.'),
  (2024, 'damit', 'so that', 'conjunction', null, null, 'B1', 2, 'communication', 'Ich erkläre es noch einmal, damit alle es verstehen.', 'I''ll explain it again so that everyone understands.', null),
  (11347, 'nicht nur ... sondern auch', 'not only ... but also', 'conjunction', null, null, 'B1', 3, 'communication', 'Sie ist nicht nur nett, sondern auch sehr klug.', 'She''s not only nice but also very smart.', null),
  (11348, 'statt', 'instead of', 'preposition', null, null, 'B1', 4, 'communication', 'Ich trinke Tee statt Kaffee.', 'I drink tea instead of coffee.', 'Also anstatt. + Genitiv in writing.'),
  (2021, 'allerdings', 'however, mind you', 'adverb', null, null, 'B1', 5, 'communication', 'Die Wohnung ist schön, allerdings etwas teuer.', 'The flat is nice, but a bit expensive, mind you.', null),
  (11350, 'falls', 'in case, if', 'conjunction', null, null, 'B1', 6, 'communication', 'Nimm einen Schirm mit, falls es regnet.', 'Take an umbrella in case it rains.', null),
  (11352, 'schließlich', 'after all, finally', 'adverb', null, null, 'B1', 7, 'communication', 'Schließlich haben wir doch eine Wohnung gefunden.', 'In the end we did find a flat.', 'Also: after all (Er ist schließlich dein Bruder).'),
  (2023, 'obwohl', 'although', 'conjunction', null, null, 'B1', 8, 'communication', 'Ich gehe joggen, obwohl es regnet.', 'I''m going jogging although it''s raining.', null),
  (11353, 'jemanden erinnern an', 'to remind someone of/about', 'verb', null, null, 'B1', 9, 'communication', 'Kannst du mich an den Termin erinnern?', 'Can you remind me about the appointment?', 'Forms: erinnert, erinnerte, hat erinnert.'),
  (11354, 'sobald', 'as soon as', 'conjunction', null, null, 'B1', 10, 'communication', 'Ich rufe dich an, sobald ich da bin.', 'I''ll call you as soon as I get there.', null),
  (11355, 'Fall', 'case, fall', 'noun', 'der', 'Fälle', 'B1', 11, 'everyday', 'In diesem Fall rufen Sie bitte an.', 'In that case please call.', 'auf jeden Fall = definitely auf keinen Fall = no way.'),
  (11356, 'entlang', 'along', 'preposition', null, null, 'B1', 12, 'communication', 'Gehen Sie die Straße entlang.', 'Go along the street.', 'Usually after the noun + Akk.'),
  (11357, 'Art', 'type, kind, way', 'noun', 'die', 'Arten', 'B1', 13, 'everyday', 'Was für eine Art Job suchst du?', 'What kind of job are you looking for?', null),
  (11359, 'Chance', 'chance, opportunity', 'noun', 'die', 'Chancen', 'B1', 14, 'work', 'Das ist eine große Chance für mich.', 'That''s a big opportunity for me.', null),
  (11360, 'erwarten', 'to expect, to wait for', 'verb', null, null, 'B1', 15, 'everyday', 'Wir erwarten Sie um zehn Uhr.', 'We''re expecting you at ten.', 'Forms: erwartet, erwartete, hat erwartet.'),
  (11361, 'verlassen', 'to leave (a place, person)', 'verb', null, null, 'B1', 16, 'everyday', 'Bitte verlassen Sie das Gebäude.', 'Please leave the building.', 'sich verlassen auf = to rely on. Forms: verlässt, verließ, hat verlassen.'),
  (11362, 'zwar ... aber', 'admittedly ... but, it''s true ... but', 'conjunction', null, null, 'B1', 17, 'communication', 'Die Wohnung ist zwar klein, aber sehr günstig.', 'The flat is small, it''s true, but very cheap.', null),
  (11363, 'Zukunft', 'future', 'noun', 'die', null, 'B1', 18, 'time', 'Was planst du für die Zukunft?', 'What are you planning for the future?', 'in Zukunft = in future.'),
  (1053, 'sich entscheiden', 'to decide', 'verb', null, null, 'B1', 19, 'everyday', 'Ich kann mich einfach nicht entscheiden.', 'I just can''t decide.', null),
  (11364, 'entscheiden', 'to decide', 'verb', null, null, 'B1', 20, 'everyday', 'Das musst du selbst entscheiden.', 'You have to decide that yourself.', 'Forms: entscheidet, entschied, hat entschieden.'),
  (11365, 'Möglichkeit', 'possibility, option, opportunity', 'noun', 'die', 'Möglichkeiten', 'B1', 21, 'everyday', 'Gibt es die Möglichkeit, online zu bezahlen?', 'Is it possible to pay online?', null),
