  (11376, 'erkennen', 'to recognise', 'verb', null, null, 'B1', 31, 'everyday', 'Ich habe dich fast nicht erkannt!', 'I almost didn''t recognise you!', 'Forms: erkennt, erkannte, hat erkannt.'),
  (11377, 'steigen', 'to rise, to climb', 'verb', null, null, 'B1', 32, 'shopping', 'Die Preise steigen immer weiter.', 'Prices keep rising.', 'Forms: steigt, stieg, ist gestiegen.'),
