  (11385, 'Richtung', 'direction', 'noun', 'die', 'Richtungen', 'B1', 39, 'transport', 'In welche Richtung muss ich gehen?', 'Which direction do I have to go?', 'Richtung Hauptbahnhof = towards the central station.'),
  (11386, 'zählen', 'to count', 'verb', null, null, 'B1', 40, 'everyday', 'Kannst du bis zehn zählen?', 'Can you count to ten?', 'zählen zu = to be one of. Forms: zählt, zählte, hat gezählt.'),
