  (14246, 'schlichtweg', 'plainly, simply', 'adverb', null, null, 'B2', 1333, 'communication', 'Das ist schlichtweg falsch.', 'That''s simply wrong.', 'Mainly to understand when reading or listening.'),
  (14247, 'neuerdings', 'recently, lately', 'adverb', null, null, 'B2', 1334, 'time', 'Neuerdings fährt er mit dem Rad.', 'He''s been cycling lately.', 'Mainly to understand when reading or listening.'),
  (14248, 'inwiefern', 'in what way, to what extent', 'adverb', null, null, 'B2', 1335, 'communication', 'Inwiefern ist das ein Problem?', 'In what way is that a problem?', 'Mainly to understand when reading or listening.'),
  (14249, 'gewissermaßen', 'to some extent, as it were', 'adverb', null, null, 'B2', 1336, 'communication', 'Das ist gewissermaßen ein Test.', 'That''s a test of sorts.', 'Mainly to understand when reading or listening.'),
  (14250, 'ausgesprochen', 'decidedly, extremely', 'adverb', null, null, 'B2', 1337, 'communication', 'Sie ist ausgesprochen freundlich.', 'She''s extremely friendly.', 'Mainly to understand when reading or listening.'),
  (14251, 'bestenfalls', 'at best', 'adverb', null, null, 'B2', 1338, 'communication', 'Wir kommen bestenfalls um acht an.', 'We''ll arrive at eight at best.', 'Mainly to understand when reading or listening.'),
  (14252, 'schlimmstenfalls', 'at worst', 'adverb', null, null, 'B2', 1339, 'communication', 'Schlimmstenfalls müssen wir den Termin verschieben.', 'At worst we''ll have to postpone the appointment.', 'Mainly to understand when reading or listening.'),
  (14253, 'erfreulicherweise', 'happily, pleasingly', 'adverb', null, null, 'B2', 1340, 'communication', 'Erfreulicherweise sind die Zahlen gestiegen.', 'Pleasingly, the figures have risen.', 'Register: formal. Mainly to understand when reading or listening.'),
  (14254, 'bedauerlicherweise', 'regrettably', 'adverb', null, null, 'B2', 1341, 'communication', 'Bedauerlicherweise müssen wir absagen.', 'Regrettably we have to cancel.', 'Register: formal. Mainly to understand when reading or listening.'),
  (14255, 'anderswo', 'elsewhere', 'adverb', null, null, 'B2', 1342, 'everyday', 'Anderswo ist es billiger.', 'It''s cheaper elsewhere.', 'Mainly to understand when reading or listening.'),
  (14258, 'Urlaubsanspruch', 'holiday entitlement', 'noun', 'der', 'Urlaubsansprüche', 'B2', 1343, 'work', 'Mein Urlaubsanspruch beträgt 28 Tage.', 'My holiday entitlement is 28 days.', 'Mainly to understand when reading or listening.'),
  (14259, 'Lohnfortzahlung', 'continued pay (during sickness)', 'noun', 'die', null, 'B2', 1344, 'work', 'Bei Krankheit gibt es sechs Wochen Lohnfortzahlung.', 'If you''re ill you get six weeks'' continued pay.', 'Mainly to understand when reading or listening.')
