-- Lernbrot: complete setup for a NEW Supabase project. Paste into Supabase SQL Editor and click Run (once).
-- Generated from supabase/migrations/* + supabase/seed/content.sql

-- ===== supabase/migrations/20261001000001_schema.sql =====
-- Germanizer MVP schema.
-- Supabase is the source of truth for content, progress, schedule and sessions.
-- Every user-owned table has RLS enabled. Clients read their own rows directly;
-- all writes except profile settings go through validated RPCs (see 0002).

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create or replace function public.cefr_rank(level text)
returns int language sql immutable as $$
  select case level when 'A1' then 1 when 'A2' then 2 when 'B1' then 3 when 'B2' then 4 end
$$;

create or replace function public.is_valid_timezone(tz text)
returns boolean language sql stable as $$
  select exists (select 1 from pg_timezone_names where name = tz)
$$;

-- ---------------------------------------------------------------------------
-- profiles (one per auth user, created by trigger)
-- ---------------------------------------------------------------------------

create table public.profiles (
  id                 uuid primary key references auth.users (id) on delete cascade,
  current_cefr_level text not null default 'A1' check (current_cefr_level in ('A1','A2','B1','B2')),
  daily_word_target  int  not null default 10 check (daily_word_target between 3 and 30),
  timezone           text not null default 'UTC' check (public.is_valid_timezone(timezone)),
  -- null until the user has completed onboarding; the daily job skips such users
  onboarded_at       timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create trigger profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  return new;
end;
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Shared content
-- ---------------------------------------------------------------------------

-- ids are explicit and stable (assigned in content/vocabulary.json); never reuse an id.
create table public.vocabulary_words (
  id                  int primary key,
  german              text not null,
  english             text not null,
  part_of_speech      text not null check (part_of_speech in
                        ('noun','verb','adjective','adverb','preposition','phrase','pronoun','conjunction')),
  article             text check (article in ('der','die','das')),
  plural              text,
  cefr_level          text not null check (cefr_level in ('A1','A2','B1','B2')),
  frequency_rank      int  not null,
  topic               text not null,
  example_sentence    text not null,
  example_translation text not null,
  usage_note          text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  check ((part_of_speech = 'noun') or (article is null and plural is null))
);

create trigger vocabulary_words_updated_at before update on public.vocabulary_words
  for each row execute function public.set_updated_at();

create index vocabulary_words_level_idx on public.vocabulary_words (cefr_level, frequency_rank);

-- content = null means "outline only" (B1/B2 in the MVP)
create table public.grammar_topics (
  id            int primary key,
  slug          text not null unique,
  title         text not null,
  cefr_level    text not null check (cefr_level in ('A1','A2','B1','B2')),
  planned_order int  not null,
  summary       text not null,
  content       jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (cefr_level, planned_order)
);

create trigger grammar_topics_updated_at before update on public.grammar_topics
  for each row execute function public.set_updated_at();

create table public.vocabulary_grammar_links (
  word_id  int not null references public.vocabulary_words (id) on delete cascade,
  topic_id int not null references public.grammar_topics (id) on delete cascade,
  primary key (word_id, topic_id)
);

-- ---------------------------------------------------------------------------
-- Learner state
-- ---------------------------------------------------------------------------

create table public.vocabulary_progress (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users (id) on delete cascade,
  word_id         int  not null references public.vocabulary_words (id) on delete cascade,
  status          text not null default 'new' check (status in ('new','learning','familiar','strong','review')),
  first_seen_at   timestamptz,
  last_seen_at    timestamptz,
  next_review_at  timestamptz,
  times_seen      int not null default 0 check (times_seen >= 0),
  times_correct   int not null default 0 check (times_correct >= 0),
  times_incorrect int not null default 0 check (times_incorrect >= 0),
  streak          int not null default 0 check (streak >= 0),
  difficulty      int not null default 0 check (difficulty between 0 and 10),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (user_id, word_id)
);

create trigger vocabulary_progress_updated_at before update on public.vocabulary_progress
  for each row execute function public.set_updated_at();

create index vocabulary_progress_due_idx on public.vocabulary_progress (user_id, next_review_at);

create table public.daily_sessions (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users (id) on delete cascade,
  session_date      date not null,
  new_word_count    int  not null,
  review_word_count int  not null,
  total_word_count  int  not null,
  status            text not null default 'ready' check (status in ('ready','completed')),
  quiz_score        int,
  created_at        timestamptz not null default now(),
  completed_at      timestamptz,
  -- makes session creation (app + daily job) idempotent
  unique (user_id, session_date),
  check (total_word_count = new_word_count + review_word_count)
);

create table public.daily_session_words (
  session_id uuid not null references public.daily_sessions (id) on delete cascade,
  word_id    int  not null references public.vocabulary_words (id),
  position   int  not null,
  kind       text not null check (kind in ('new','review')),
  primary key (session_id, word_id),
  unique (session_id, position)
);

create table public.quiz_attempts (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  -- one scored attempt per daily session, so a word's schedule is updated once per day
  daily_session_id uuid not null unique references public.daily_sessions (id) on delete cascade,
  quiz_date        date not null,
  score            int  not null check (score >= 0),
  total_questions  int  not null check (total_questions > 0 and score <= total_questions),
  duration_seconds int  not null check (duration_seconds >= 0),
  created_at       timestamptz not null default now()
);

create index quiz_attempts_user_idx on public.quiz_attempts (user_id, quiz_date desc);

create table public.quiz_answers (
  id              uuid primary key default gen_random_uuid(),
  quiz_attempt_id uuid not null references public.quiz_attempts (id) on delete cascade,
  word_id         int  not null references public.vocabulary_words (id),
  question_type   text not null check (question_type in
                    ('de_en','en_de','context','fill_blank','en_de_typed','article','plural')),
  user_answer     text not null,
  correct_answer  text not null,
  is_correct      boolean not null,
  created_at      timestamptz not null default now()
);

-- Audit trail for the cloud job, so "did it run while my PC was off?" is answerable.
create table public.daily_job_runs (
  id               bigint generated always as identity primary key,
  ran_at           timestamptz not null default now(),
  profiles_checked int not null,
  sessions_created int not null
);

-- ---------------------------------------------------------------------------
-- Privileges + Row Level Security
-- ---------------------------------------------------------------------------

alter table public.profiles                 enable row level security;
alter table public.vocabulary_words         enable row level security;
alter table public.grammar_topics           enable row level security;
alter table public.vocabulary_grammar_links enable row level security;
alter table public.vocabulary_progress      enable row level security;
alter table public.daily_sessions           enable row level security;
alter table public.daily_session_words      enable row level security;
alter table public.quiz_attempts            enable row level security;
alter table public.quiz_answers             enable row level security;
alter table public.daily_job_runs           enable row level security;

-- Start from nothing, then grant exactly what the app needs.
revoke all on all tables in schema public from anon, authenticated;

grant select on public.vocabulary_words, public.grammar_topics, public.vocabulary_grammar_links to authenticated;
grant select on public.profiles, public.vocabulary_progress, public.daily_sessions,
               public.daily_session_words, public.quiz_attempts, public.quiz_answers to authenticated;
-- profile settings are the only direct client write
grant update (current_cefr_level, daily_word_target, timezone, onboarded_at) on public.profiles to authenticated;

create policy "content readable by signed-in users" on public.vocabulary_words
  for select to authenticated using (true);
create policy "grammar readable by signed-in users" on public.grammar_topics
  for select to authenticated using (true);
create policy "links readable by signed-in users" on public.vocabulary_grammar_links
  for select to authenticated using (true);

create policy "own profile: read" on public.profiles
  for select to authenticated using (id = auth.uid());
create policy "own profile: update" on public.profiles
  for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

create policy "own progress: read" on public.vocabulary_progress
  for select to authenticated using (user_id = auth.uid());

create policy "own sessions: read" on public.daily_sessions
  for select to authenticated using (user_id = auth.uid());

create policy "own session words: read" on public.daily_session_words
  for select to authenticated using (
    exists (select 1 from public.daily_sessions s where s.id = session_id and s.user_id = auth.uid()));

create policy "own attempts: read" on public.quiz_attempts
  for select to authenticated using (user_id = auth.uid());

create policy "own answers: read" on public.quiz_answers
  for select to authenticated using (
    exists (select 1 from public.quiz_attempts a where a.id = quiz_attempt_id and a.user_id = auth.uid()));

-- daily_job_runs: RLS on, no policies -> invisible to anon/authenticated.

-- ===== supabase/migrations/20261001000002_functions.sql =====
-- Deterministic learning logic that must run in the cloud (the daily job runs
-- inside Postgres via pg_cron, so session selection lives here, next to the data).
-- Spaced-repetition intervals are computed in TypeScript (src/lib/spacedRepetition)
-- and submitted through submit_quiz(), which validates and stores them atomically.

-- ---------------------------------------------------------------------------
-- create_daily_session_for: the single implementation of "Today's 10".
-- Idempotent: returns the existing session for (user, date) if there is one.
-- Internal: callable by the job (postgres) and by create_my_daily_session().
-- ---------------------------------------------------------------------------
create or replace function public.create_daily_session_for(p_user_id uuid, p_session_date date)
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_profile    public.profiles;
  v_session    public.daily_sessions;
  v_target     int;
  v_min_new    int;
  v_day_start  timestamptz;
  v_day_end    timestamptz;
  v_user_rank  int;
  v_new_avail  int;
  v_review_cap int;
  v_due        int[];
  v_struggling int[];
  v_reviews    int[];
  v_new        int[];
  v_fill       int[];
begin
  select * into v_session from daily_sessions
   where user_id = p_user_id and session_date = p_session_date;
  if found then
    return v_session;
  end if;

  select * into v_profile from profiles where id = p_user_id;
  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  v_target    := v_profile.daily_word_target;
  -- keep a trickle of new words even when many reviews are overdue (10 -> at least 2 new)
  v_min_new   := ceil(v_target * 0.2)::int;
  v_day_start := p_session_date::timestamp at time zone v_profile.timezone;
  v_day_end   := (p_session_date + 1)::timestamp at time zone v_profile.timezone;
  v_user_rank := cefr_rank(v_profile.current_cefr_level);

  select count(*) into v_new_avail
    from vocabulary_words w
   where not exists (select 1 from vocabulary_progress p
                      where p.user_id = p_user_id and p.word_id = w.id);

  v_review_cap := v_target - least(v_min_new, v_new_avail);

  -- 1. Words due for review by the end of the learner's local day.
  --    Frequently-wrong words first, then the most overdue.
  v_due := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at < v_day_end
     order by (p.times_incorrect > p.times_correct) desc, p.next_review_at, p.difficulty desc, p.word_id
     limit v_review_cap);

  -- 2. Up to two frequently-wrong words that are not due yet (not seen today).
  v_struggling := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at >= v_day_end
       and p.times_incorrect >= 2
       and p.times_incorrect >= p.times_correct
       and p.last_seen_at < v_day_start
     order by p.times_incorrect - p.times_correct desc, p.difficulty desc, p.word_id
     limit least(2, v_review_cap - cardinality(v_due)));

  v_reviews := v_due || v_struggling;

  -- 3. New words: learner's level first, then lower levels, then higher ones.
  --    Within a level, interleave topics (topic_rank) by frequency for variety.
  v_new := array(
    select c.id
      from (
        select w.id,
               w.frequency_rank,
               case
                 when cefr_rank(w.cefr_level) = v_user_rank then 0
                 when cefr_rank(w.cefr_level) < v_user_rank then v_user_rank - cefr_rank(w.cefr_level)
                 else 3 + cefr_rank(w.cefr_level) - v_user_rank
               end as level_priority,
               w.topic
          from vocabulary_words w
         where not exists (select 1 from vocabulary_progress p
                            where p.user_id = p_user_id and p.word_id = w.id)
      ) c
     order by c.level_priority,
              row_number() over (partition by c.level_priority, c.topic order by c.frequency_rank, c.id),
              c.frequency_rank,
              c.id
     limit v_target - cardinality(v_reviews));

  -- 4. Out of new words: top up with the earliest upcoming reviews.
  if cardinality(v_reviews) + cardinality(v_new) < v_target then
    v_fill := array(
      select p.word_id
        from vocabulary_progress p
       where p.user_id = p_user_id
         and p.word_id <> all (v_reviews)
       order by p.next_review_at nulls first, p.word_id
       limit v_target - cardinality(v_reviews) - cardinality(v_new));
    v_reviews := v_reviews || v_fill;
  end if;

  values (p_user_id, p_session_date, cardinality(v_new), cardinality(v_reviews),
          cardinality(v_new) + cardinality(v_reviews))
  on conflict (user_id, session_date) do nothing
  returning * into v_session;

  if not found then
    -- a concurrent call created it first
    select * into v_session from daily_sessions
     where user_id = p_user_id and session_date = p_session_date;
    return v_session;
  end if;

  select v_session.id, x.word_id, x.ord::int, 'new'
    from unnest(v_new) with ordinality as x(word_id, ord);

  select v_session.id, x.word_id, cardinality(v_new) + x.ord::int, 'review'
    from unnest(v_reviews) with ordinality as x(word_id, ord);

  update vocabulary_progress
     set status = 'review'
   where user_id = p_user_id and word_id = any (v_reviews);

  return v_session;
end;
$$;

-- ---------------------------------------------------------------------------
-- create_my_daily_session: what the app calls. Uses the caller's own timezone.
-- ---------------------------------------------------------------------------
create or replace function public.create_my_daily_session()
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_tz  text;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select timezone into v_tz from profiles where id = v_uid and onboarded_at is not null;
  if not found then
    raise exception 'complete onboarding first';
  end if;

  return create_daily_session_for(v_uid, (now() at time zone v_tz)::date);
end;
$$;

-- ---------------------------------------------------------------------------
-- submit_quiz: stores the attempt, every answer, and the new review schedule
-- in one transaction. One scored attempt per session.
--
-- p_answers:  [{word_id, question_type, user_answer, correct_answer, is_correct}]
-- p_schedule: [{word_id, status, streak, difficulty, next_review_at}]  (from spacedRepetition)
-- ---------------------------------------------------------------------------
create or replace function public.submit_quiz(
  p_session_id       uuid,
  p_duration_seconds int,
  p_answers          jsonb,
  p_schedule         jsonb)
returns public.quiz_attempts
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_now     timestamptz := now();
  v_session public.daily_sessions;
  v_attempt public.quiz_attempts;
  v_score   int;
  v_total   int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select * into v_session from daily_sessions
   where id = p_session_id and user_id = v_uid
   for update;
  if not found then
    raise exception 'session not found';
  end if;
  if v_session.status = 'completed' then
    raise exception 'session already completed';
  end if;

  if jsonb_typeof(p_answers) is distinct from 'array' or jsonb_typeof(p_schedule) is distinct from 'array' then
    raise exception 'answers and schedule must be arrays';
  end if;

  -- exactly one answer per session word
  if (select count(*) from jsonb_to_recordset(p_answers) a(word_id int)) <> v_session.total_word_count
     or (select count(distinct a.word_id) from jsonb_to_recordset(p_answers) a(word_id int)) <> v_session.total_word_count
     or exists (select 1 from jsonb_to_recordset(p_answers) a(word_id int)
                 where not exists (select 1 from daily_session_words sw
                                    where sw.session_id = p_session_id and sw.word_id = a.word_id)) then
    raise exception 'answers must cover each session word exactly once';
  end if;

  -- exactly one schedule entry per answered word, with sane values
  if (select count(*) from jsonb_to_recordset(p_schedule) s(word_id int)) <> v_session.total_word_count
     or (select count(distinct s.word_id) from jsonb_to_recordset(p_schedule) s(word_id int)) <> v_session.total_word_count
     or exists (select 1 from jsonb_to_recordset(p_schedule) s(word_id int)
                 where not exists (select 1 from daily_session_words sw
                                    where sw.session_id = p_session_id and sw.word_id = s.word_id))
     or exists (select 1 from jsonb_to_recordset(p_schedule) s(status text, next_review_at timestamptz)
                 where s.status is null or s.status not in ('learning','familiar','strong')
                    or s.next_review_at is null
                    or s.next_review_at <= v_now
                    or s.next_review_at > v_now + interval '400 days') then
    raise exception 'invalid schedule';
  end if;

  select count(*) filter (where a.is_correct), count(*)
    into v_score, v_total
    from jsonb_to_recordset(p_answers) a(is_correct boolean);

  values (v_uid, p_session_id, v_session.session_date, v_score, v_total,
          greatest(0, coalesce(p_duration_seconds, 0)))
  returning * into v_attempt;

  select v_attempt.id, a.word_id, a.question_type, coalesce(a.user_answer, ''), a.correct_answer, a.is_correct
    from jsonb_to_recordset(p_answers)
         a(word_id int, question_type text, user_answer text, correct_answer text, is_correct boolean);

          first_seen_at, last_seen_at, times_seen, times_correct, times_incorrect)
  select v_uid, s.word_id, s.status, s.streak, s.difficulty, s.next_review_at,
         v_now, v_now, 1,
         case when a.is_correct then 1 else 0 end,
         case when a.is_correct then 0 else 1 end
    from jsonb_to_recordset(p_schedule)
         s(word_id int, status text, streak int, difficulty int, next_review_at timestamptz)
    join jsonb_to_recordset(p_answers) a(word_id int, is_correct boolean) using (word_id)
  on conflict (user_id, word_id) do update set
    status          = excluded.status,
    streak          = excluded.streak,
    difficulty      = excluded.difficulty,
    next_review_at  = excluded.next_review_at,
    first_seen_at   = coalesce(p.first_seen_at, excluded.first_seen_at),
    last_seen_at    = excluded.last_seen_at,
    times_seen      = p.times_seen + 1,
    times_correct   = p.times_correct + excluded.times_correct,
    times_incorrect = p.times_incorrect + excluded.times_incorrect;

  update daily_sessions
     set status = 'completed', quiz_score = v_score, completed_at = v_now
   where id = p_session_id;

  return v_attempt;
end;
$$;

-- ---------------------------------------------------------------------------
-- run_daily_learning_job: the cloud job (scheduled hourly by pg_cron, 0003).
-- For each onboarded learner whose local time is past p_min_local_hour and who
-- has no session for their local date yet, prepares today's session.
-- Hourly + local-hour gate = every timezone gets its session early in its morning.
-- ---------------------------------------------------------------------------
create or replace function public.run_daily_learning_job(
  p_now            timestamptz default now(),
  p_min_local_hour int default 3)
returns int
language plpgsql security definer set search_path = public as $$
declare
  r         record;
  v_local   timestamp;
  v_checked int := 0;
  v_created int := 0;
begin
  for r in select id, timezone from profiles where onboarded_at is not null order by id loop
    v_checked := v_checked + 1;
    v_local := p_now at time zone r.timezone;
    if extract(hour from v_local) >= p_min_local_hour
       and not exists (select 1 from daily_sessions
                        where user_id = r.id and session_date = v_local::date) then
      begin
        perform create_daily_session_for(r.id, v_local::date);
        v_created := v_created + 1;
      exception when others then
        -- one bad profile must not stop everyone else's lesson
        raise warning 'daily session for % failed: %', r.id, sqlerrm;
      end;
    end if;
  end loop;

  return v_created;
end;
$$;

-- ---------------------------------------------------------------------------
-- Function privileges: internal functions are not callable from the API.
-- ---------------------------------------------------------------------------
revoke execute on function public.create_daily_session_for(uuid, date) from public, anon, authenticated;
revoke execute on function public.run_daily_learning_job(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

revoke execute on function public.create_my_daily_session() from public, anon;
revoke execute on function public.submit_quiz(uuid, int, jsonb, jsonb) from public, anon;
grant  execute on function public.create_my_daily_session() to authenticated;
grant  execute on function public.submit_quiz(uuid, int, jsonb, jsonb) to authenticated;

-- ===== supabase/migrations/20261001000003_daily_cron.sql =====
-- Cloud scheduling: pg_cron runs inside the Supabase database, so the daily job
-- keeps running when the learner's PC is off.
--
-- Runs at minute 5 of every hour. run_daily_learning_job() only creates a session
-- once the learner's local time is past 03:00 and none exists for their local date,
-- so running hourly serves every timezone and repeated runs are harmless.

create extension if not exists pg_cron;

-- cron.schedule with an existing job name replaces that job (safe to re-run).
select cron.schedule(
  'germanizer-daily-learning-job',
  '5 * * * *',
  $$select public.run_daily_learning_job()$$
);

-- ===== supabase/migrations/20261005000004_resume_and_target.sql =====
-- 1. Resume where you left off: the study card position and each quiz answer are
--    saved as the learner goes, so leaving the lesson (or switching device) loses nothing.
-- 2. Daily word target: 5..50 in steps of 5, changeable at any time.

-- ---------------------------------------------------------------------------
-- Resume state on the session
-- ---------------------------------------------------------------------------
alter table public.daily_sessions
  add column if not exists study_position int not null default 0 check (study_position >= 0),
  -- {"startedAt": timestamptz, "answers": {"<wordId>:<type>": "<answer>"}}
  add column if not exists quiz_draft jsonb not null default '{}'::jsonb;

-- ---------------------------------------------------------------------------
-- Daily target: 5..50, multiples of 5
-- ---------------------------------------------------------------------------
update public.profiles
   set daily_word_target = least(50, greatest(5, (round(daily_word_target / 5.0) * 5)::int))
 where daily_word_target not between 5 and 50 or daily_word_target % 5 <> 0;

alter table public.profiles drop constraint if exists profiles_daily_word_target_check;
alter table public.profiles add constraint profiles_daily_word_target_check
  check (daily_word_target between 5 and 50 and daily_word_target % 5 = 0);

-- ---------------------------------------------------------------------------
-- save_session_progress: called after every study card and every quiz answer.
-- The study position only moves forward; a saved quiz answer is never overwritten.
-- ---------------------------------------------------------------------------
create or replace function public.save_session_progress(
  p_session_id     uuid,
  p_study_position int  default null,
  p_question_id    text default null,
  p_answer         text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_session public.daily_sessions;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select * into v_session from daily_sessions
   where id = p_session_id and user_id = v_uid
   for update;
  if not found then
    raise exception 'session not found';
  end if;
  if v_session.status = 'completed' then
    raise exception 'session already completed';
  end if;

  if p_question_id is not null then
    -- question ids look like "<wordId>:<type>" and must belong to this session
    if p_question_id !~ '^[0-9]{1,9}:[a-z_]{1,20}$'
       or p_answer is null or length(p_answer) > 200
       or not exists (select 1 from daily_session_words sw
                       where sw.session_id = p_session_id
                         and sw.word_id = split_part(p_question_id, ':', 1)::int) then
      raise exception 'invalid answer';
    end if;
  end if;

  update daily_sessions s
     set study_position = case
           when p_study_position is null then s.study_position
           else greatest(s.study_position, least(p_study_position, s.total_word_count))
         end,
         quiz_draft = case
           when p_question_id is null then s.quiz_draft
           else jsonb_build_object(
                  'startedAt', coalesce(s.quiz_draft -> 'startedAt', to_jsonb(now())),
                  -- right side wins in ||, so an answer that is already saved is kept
                  'answers', jsonb_build_object(p_question_id, p_answer)
                             || coalesce(s.quiz_draft -> 'answers', '{}'::jsonb))
         end
   where s.id = p_session_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- update_daily_target: saves the new target. If today's session has not been
-- touched yet, it is rebuilt with the new size right away.
-- Returns {"profile": <row>, "today_updated": bool}.
-- ---------------------------------------------------------------------------
create or replace function public.update_daily_target(p_target int)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_profile public.profiles;
  v_today   date;
  v_rebuilt boolean := false;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  update profiles set daily_word_target = p_target where id = v_uid returning * into v_profile;
  if not found then
    raise exception 'profile not found';
  end if;

  if v_profile.onboarded_at is not null then
    v_today := (now() at time zone v_profile.timezone)::date;
    delete from daily_sessions
     where user_id = v_uid
       and session_date = v_today
       and status = 'ready'
       and study_position = 0
       and quiz_draft = '{}'::jsonb
       and total_word_count <> p_target;
    if found then
      perform create_daily_session_for(v_uid, v_today);
      v_rebuilt := true;
    end if;
  end if;

  return jsonb_build_object('profile', to_jsonb(v_profile), 'today_updated', v_rebuilt);
end;
$$;

revoke execute on function public.save_session_progress(uuid, int, text, text) from public, anon;
revoke execute on function public.update_daily_target(int) from public, anon;
grant  execute on function public.save_session_progress(uuid, int, text, text) to authenticated;
grant  execute on function public.update_daily_target(int) to authenticated;

-- make the API see the new columns and functions immediately
notify pgrst, 'reload schema';

-- ===== supabase/migrations/20261005000005_adaptive_new_words.sql =====
-- New words adapt to the review backlog (found by a 60-day simulation: with a fixed
-- minimum of 2 new words a day at 10 words/day, overdue reviews grew without limit).
-- Replaces create_daily_session_for from 20261001000002_functions.sql; same signature.

-- ---------------------------------------------------------------------------
-- create_daily_session_for: the single implementation of "Today's 10".
-- Idempotent: returns the existing session for (user, date) if there is one.
-- Internal: callable by the job (postgres) and by create_my_daily_session().
-- ---------------------------------------------------------------------------
create or replace function public.create_daily_session_for(p_user_id uuid, p_session_date date)
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_profile    public.profiles;
  v_session    public.daily_sessions;
  v_target     int;
  v_min_new    int;
  v_day_start  timestamptz;
  v_day_end    timestamptz;
  v_user_rank  int;
  v_new_avail  int;
  v_due_count  int;
  v_review_cap int;
  v_due        int[];
  v_struggling int[];
  v_reviews    int[];
  v_new        int[];
  v_fill       int[];
begin
  select * into v_session from daily_sessions
   where user_id = p_user_id and session_date = p_session_date;
  if found then
    return v_session;
  end if;

  select * into v_profile from profiles where id = p_user_id;
  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  v_target    := v_profile.daily_word_target;
  v_day_start := p_session_date::timestamp at time zone v_profile.timezone;
  v_day_end   := (p_session_date + 1)::timestamp at time zone v_profile.timezone;
  v_user_rank := cefr_rank(v_profile.current_cefr_level);

  -- How many new words to keep, depending on the review backlog:
  --   up to the target due      -> at least 20% new (10 -> 2)
  --   1x..2x the target due     -> at least 10% new (10 -> 1)
  --   2x the target or more due -> catch-up day, no new words until the backlog shrinks
  -- Forcing new words in while reviews pile up makes the backlog grow without limit.
  select count(*) into v_due_count
    from vocabulary_progress p
   where p.user_id = p_user_id and p.next_review_at < v_day_end;
  v_min_new := case
                 when v_due_count <= v_target    then ceil(v_target * 0.2)::int
                 when v_due_count < 2 * v_target then ceil(v_target * 0.1)::int
                 else 0
               end;

  select count(*) into v_new_avail
    from vocabulary_words w
   where not exists (select 1 from vocabulary_progress p
                      where p.user_id = p_user_id and p.word_id = w.id);

  v_review_cap := v_target - least(v_min_new, v_new_avail);

  -- 1. Words due for review by the end of the learner's local day.
  --    Frequently-wrong words first, then the most overdue.
  v_due := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at < v_day_end
     order by (p.times_incorrect > p.times_correct) desc, p.next_review_at, p.difficulty desc, p.word_id
     limit v_review_cap);

  -- 2. Up to two frequently-wrong words that are not due yet (not seen today).
  v_struggling := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at >= v_day_end
       and p.times_incorrect >= 2
       and p.times_incorrect >= p.times_correct
       and p.last_seen_at < v_day_start
     order by p.times_incorrect - p.times_correct desc, p.difficulty desc, p.word_id
     limit least(2, v_review_cap - cardinality(v_due)));

  v_reviews := v_due || v_struggling;

  -- 3. New words: learner's level first, then lower levels, then higher ones.
  --    Within a level, interleave topics (topic_rank) by frequency for variety.
  v_new := array(
    select c.id
      from (
        select w.id,
               w.frequency_rank,
               case
                 when cefr_rank(w.cefr_level) = v_user_rank then 0
                 when cefr_rank(w.cefr_level) < v_user_rank then v_user_rank - cefr_rank(w.cefr_level)
                 else 3 + cefr_rank(w.cefr_level) - v_user_rank
               end as level_priority,
               w.topic
          from vocabulary_words w
         where not exists (select 1 from vocabulary_progress p
                            where p.user_id = p_user_id and p.word_id = w.id)
      ) c
     order by c.level_priority,
              row_number() over (partition by c.level_priority, c.topic order by c.frequency_rank, c.id),
              c.frequency_rank,
              c.id
     limit v_target - cardinality(v_reviews));

  -- 4. Out of new words: top up with the earliest upcoming reviews.
  if cardinality(v_reviews) + cardinality(v_new) < v_target then
    v_fill := array(
      select p.word_id
        from vocabulary_progress p
       where p.user_id = p_user_id
         and p.word_id <> all (v_reviews)
       order by p.next_review_at nulls first, p.word_id
       limit v_target - cardinality(v_reviews) - cardinality(v_new));
    v_reviews := v_reviews || v_fill;
  end if;

  values (p_user_id, p_session_date, cardinality(v_new), cardinality(v_reviews),
          cardinality(v_new) + cardinality(v_reviews))
  on conflict (user_id, session_date) do nothing
  returning * into v_session;

  if not found then
    -- a concurrent call created it first
    select * into v_session from daily_sessions
     where user_id = p_user_id and session_date = p_session_date;
    return v_session;
  end if;

  select v_session.id, x.word_id, x.ord::int, 'new'
    from unnest(v_new) with ordinality as x(word_id, ord);

  select v_session.id, x.word_id, cardinality(v_new) + x.ord::int, 'review'
    from unnest(v_reviews) with ordinality as x(word_id, ord);

  update vocabulary_progress
     set status = 'review'
   where user_id = p_user_id and word_id = any (v_reviews);

  return v_session;
end;
$$;

revoke execute on function public.create_daily_session_for(uuid, date) from public, anon, authenticated;

-- ===== supabase/migrations/20261006000006_fsrs.sql =====
-- FSRS memory model (research/review-strategy/review-strategy.md).
-- 1. Each word's progress stores an FSRS memory state: stability (days until predicted recall falls
--    to 90 %), fsrs_difficulty (1..10) and the time of the last scored review. The browser computes
--    the next state with ts-fsrs (FSRS-6 default parameters) and submit_quiz validates and stores it.
-- 2. Review gaps keep growing (max 5 years) instead of stopping at 60 days.
-- 3. Due reviews are ordered by predicted recall: the word most likely forgotten comes first.
-- streak / status / difficulty are kept: the quiz uses streak for question difficulty, the UI shows status.
-- submit_quiz p_schedule entries now also carry stability and fsrs_difficulty.

alter table public.vocabulary_progress
  add column if not exists stability       double precision check (stability > 0),
  add column if not exists fsrs_difficulty double precision check (fsrs_difficulty between 1 and 10),
  add column if not exists last_review_at  timestamptz;

-- Existing rows: start from the old schedule. The old interval becomes the stability (recall ~90 % when
-- due), old difficulty 0..10 maps to 3..10. Safe to re-run: only rows without a state are touched.
update public.vocabulary_progress
   set stability = greatest(1, round(extract(epoch from (next_review_at - last_seen_at)) / 86400)),
       fsrs_difficulty = least(10, 3 + 0.7 * difficulty),
       last_review_at = last_seen_at
 where stability is null and last_seen_at is not null and next_review_at is not null;

-- Predicted recall probability (FSRS-6 forgetting curve, default decay 0.1542). Unknown state = 0,
-- so such words sort first.
create or replace function public.fsrs_retrievability(p_stability double precision, p_last_review timestamptz, p_at timestamptz)
returns double precision
language sql immutable as $$
  select case
           when p_stability is null or p_last_review is null then 0
           else power(1 + (power(0.9, -1 / 0.1542) - 1)
                          * greatest(0, extract(epoch from (p_at - p_last_review)) / 86400) / p_stability,
                      -0.1542)
         end
$$;

create or replace function public.create_daily_session_for(p_user_id uuid, p_session_date date)
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_profile    public.profiles;
  v_session    public.daily_sessions;
  v_target     int;
  v_min_new    int;
  v_day_start  timestamptz;
  v_day_end    timestamptz;
  v_user_rank  int;
  v_new_avail  int;
  v_due_count  int;
  v_review_cap int;
  v_due        int[];
  v_struggling int[];
  v_reviews    int[];
  v_new        int[];
  v_fill       int[];
begin
  select * into v_session from daily_sessions
   where user_id = p_user_id and session_date = p_session_date;
  if found then
    return v_session;
  end if;

  select * into v_profile from profiles where id = p_user_id;
  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  v_target    := v_profile.daily_word_target;
  v_day_start := p_session_date::timestamp at time zone v_profile.timezone;
  v_day_end   := (p_session_date + 1)::timestamp at time zone v_profile.timezone;
  v_user_rank := cefr_rank(v_profile.current_cefr_level);

  -- How many new words to keep, depending on the review backlog:
  --   up to the target due      -> at least 20% new (10 -> 2)
  --   1x..2x the target due     -> at least 10% new (10 -> 1)
  --   2x the target or more due -> catch-up day, no new words until the backlog shrinks
  -- Forcing new words in while reviews pile up makes the backlog grow without limit.
  select count(*) into v_due_count
    from vocabulary_progress p
   where p.user_id = p_user_id and p.next_review_at < v_day_end;
  v_min_new := case
                 when v_due_count <= v_target    then ceil(v_target * 0.2)::int
                 when v_due_count < 2 * v_target then ceil(v_target * 0.1)::int
                 else 0
               end;

  select count(*) into v_new_avail
    from vocabulary_words w
   where not exists (select 1 from vocabulary_progress p
                      where p.user_id = p_user_id and p.word_id = w.id);

  v_review_cap := v_target - least(v_min_new, v_new_avail);

  -- 1. Words due for review by the end of the learner's local day.
  --    Frequently-wrong words first, then the ones most likely forgotten (lowest predicted recall).
  v_due := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at < v_day_end
     order by (p.times_incorrect > p.times_correct) desc,
              fsrs_retrievability(p.stability, coalesce(p.last_review_at, p.last_seen_at), v_day_start),
              p.next_review_at, p.word_id
     limit v_review_cap);

  -- 2. Up to two frequently-wrong words that are not due yet (not seen today).
  v_struggling := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at >= v_day_end
       and p.times_incorrect >= 2
       and p.times_incorrect >= p.times_correct
       and p.last_seen_at < v_day_start
     order by p.times_incorrect - p.times_correct desc, p.difficulty desc, p.word_id
     limit least(2, v_review_cap - cardinality(v_due)));

  v_reviews := v_due || v_struggling;

  -- 3. New words: learner's level first, then lower levels, then higher ones.
  --    Within a level, interleave topics (topic_rank) by frequency for variety.
  v_new := array(
    select c.id
      from (
        select w.id,
               w.frequency_rank,
               case
                 when cefr_rank(w.cefr_level) = v_user_rank then 0
                 when cefr_rank(w.cefr_level) < v_user_rank then v_user_rank - cefr_rank(w.cefr_level)
                 else 3 + cefr_rank(w.cefr_level) - v_user_rank
               end as level_priority,
               w.topic
          from vocabulary_words w
         where not exists (select 1 from vocabulary_progress p
                            where p.user_id = p_user_id and p.word_id = w.id)
      ) c
     order by c.level_priority,
              row_number() over (partition by c.level_priority, c.topic order by c.frequency_rank, c.id),
              c.frequency_rank,
              c.id
     limit v_target - cardinality(v_reviews));

  -- 4. Out of new words: top up with the earliest upcoming reviews.
  if cardinality(v_reviews) + cardinality(v_new) < v_target then
    v_fill := array(
      select p.word_id
        from vocabulary_progress p
       where p.user_id = p_user_id
         and p.word_id <> all (v_reviews)
       order by p.next_review_at nulls first, p.word_id
       limit v_target - cardinality(v_reviews) - cardinality(v_new));
    v_reviews := v_reviews || v_fill;
  end if;

  values (p_user_id, p_session_date, cardinality(v_new), cardinality(v_reviews),
          cardinality(v_new) + cardinality(v_reviews))
  on conflict (user_id, session_date) do nothing
  returning * into v_session;

  if not found then
    -- a concurrent call created it first
    select * into v_session from daily_sessions
     where user_id = p_user_id and session_date = p_session_date;
    return v_session;
  end if;

  select v_session.id, x.word_id, x.ord::int, 'new'
    from unnest(v_new) with ordinality as x(word_id, ord);

  select v_session.id, x.word_id, cardinality(v_new) + x.ord::int, 'review'
    from unnest(v_reviews) with ordinality as x(word_id, ord);

  update vocabulary_progress
     set status = 'review'
   where user_id = p_user_id and word_id = any (v_reviews);

  return v_session;
end;
$$;

create or replace function public.submit_quiz(
  p_session_id       uuid,
  p_duration_seconds int,
  p_answers          jsonb,
  p_schedule         jsonb)
returns public.quiz_attempts
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_now     timestamptz := now();
  v_session public.daily_sessions;
  v_attempt public.quiz_attempts;
  v_score   int;
  v_total   int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select * into v_session from daily_sessions
   where id = p_session_id and user_id = v_uid
   for update;
  if not found then
    raise exception 'session not found';
  end if;
  if v_session.status = 'completed' then
    raise exception 'session already completed';
  end if;

  if jsonb_typeof(p_answers) is distinct from 'array' or jsonb_typeof(p_schedule) is distinct from 'array' then
    raise exception 'answers and schedule must be arrays';
  end if;

  -- exactly one answer per session word
  if (select count(*) from jsonb_to_recordset(p_answers) a(word_id int)) <> v_session.total_word_count
     or (select count(distinct a.word_id) from jsonb_to_recordset(p_answers) a(word_id int)) <> v_session.total_word_count
     or exists (select 1 from jsonb_to_recordset(p_answers) a(word_id int)
                 where not exists (select 1 from daily_session_words sw
                                    where sw.session_id = p_session_id and sw.word_id = a.word_id)) then
    raise exception 'answers must cover each session word exactly once';
  end if;

  -- exactly one schedule entry per answered word, with sane values
  if (select count(*) from jsonb_to_recordset(p_schedule) s(word_id int)) <> v_session.total_word_count
     or (select count(distinct s.word_id) from jsonb_to_recordset(p_schedule) s(word_id int)) <> v_session.total_word_count
     or exists (select 1 from jsonb_to_recordset(p_schedule) s(word_id int)
                 where not exists (select 1 from daily_session_words sw
                                    where sw.session_id = p_session_id and sw.word_id = s.word_id))
     or exists (select 1 from jsonb_to_recordset(p_schedule)
                         s(status text, next_review_at timestamptz, stability double precision, fsrs_difficulty double precision)
                 where s.status is null or s.status not in ('learning','familiar','strong')
                    or s.next_review_at is null
                    or s.next_review_at <= v_now
                    or s.next_review_at > v_now + interval '1830 days'
                    -- memory state: both or neither (an app version from before this migration sends neither)
                    or (s.stability is null) <> (s.fsrs_difficulty is null)
                    or s.stability < 0.001 or s.stability > 36500
                    or s.fsrs_difficulty < 1 or s.fsrs_difficulty > 10) then
    raise exception 'invalid schedule';
  end if;

  select count(*) filter (where a.is_correct), count(*)
    into v_score, v_total
    from jsonb_to_recordset(p_answers) a(is_correct boolean);

  values (v_uid, p_session_id, v_session.session_date, v_score, v_total,
          greatest(0, coalesce(p_duration_seconds, 0)))
  returning * into v_attempt;

  select v_attempt.id, a.word_id, a.question_type, coalesce(a.user_answer, ''), a.correct_answer, a.is_correct
    from jsonb_to_recordset(p_answers)
         a(word_id int, question_type text, user_answer text, correct_answer text, is_correct boolean);

          first_seen_at, last_seen_at, times_seen, times_correct, times_incorrect)
  select v_uid, s.word_id, s.status, s.streak, s.difficulty, s.next_review_at, s.stability, s.fsrs_difficulty,
         case when s.stability is null then null else v_now end,
         v_now, v_now, 1,
         case when a.is_correct then 1 else 0 end,
         case when a.is_correct then 0 else 1 end
    from jsonb_to_recordset(p_schedule)
         s(word_id int, status text, streak int, difficulty int, next_review_at timestamptz,
           stability double precision, fsrs_difficulty double precision)
    join jsonb_to_recordset(p_answers) a(word_id int, is_correct boolean) using (word_id)
  on conflict (user_id, word_id) do update set
    status          = excluded.status,
    streak          = excluded.streak,
    difficulty      = excluded.difficulty,
    next_review_at  = excluded.next_review_at,
    -- without a memory state in the submission, keep the stored one untouched
    stability       = coalesce(excluded.stability, p.stability),
    fsrs_difficulty = coalesce(excluded.fsrs_difficulty, p.fsrs_difficulty),
    last_review_at  = case when excluded.stability is null then p.last_review_at else excluded.last_review_at end,
    first_seen_at   = coalesce(p.first_seen_at, excluded.first_seen_at),
    last_seen_at    = excluded.last_seen_at,
    times_seen      = p.times_seen + 1,
    times_correct   = p.times_correct + excluded.times_correct,
    times_incorrect = p.times_incorrect + excluded.times_incorrect;

  update daily_sessions
     set status = 'completed', quiz_score = v_score, completed_at = v_now
   where id = p_session_id;

  return v_attempt;
end;
$$;

revoke execute on function public.fsrs_retrievability(double precision, timestamptz, timestamptz) from public, anon, authenticated;
revoke execute on function public.create_daily_session_for(uuid, date) from public, anon, authenticated;
revoke execute on function public.submit_quiz(uuid, int, jsonb, jsonb) from public, anon;
grant  execute on function public.submit_quiz(uuid, int, jsonb, jsonb) to authenticated;

-- ===== supabase/migrations/20261007000007_grammar_practice.sql =====
-- Grammar practice (research/grammar-strategy/grammar-strategy.md).
-- Lessons are split into small skills (grammar_skills, seeded from content/grammar/*.txt). After
-- practising a skill on its lesson page it is "studied" and gets an FSRS memory state like a word;
-- each daily session then adds up to 3 due grammar skills (extra to the words-per-day target),
-- mixed across topics. Every grammar answer is stored with an error category for the weak-spot view.

create table if not exists public.grammar_skills (
  id         int  primary key,
  topic_id   int  not null references public.grammar_topics (id) on delete cascade,
  slug       text not null unique,
  title      text not null,
  category   text not null check (category in ('case','gender','verb_form','word_order','adjective_ending','preposition','pronoun','negation','tense','mood','other')),
  requires   int[] not null default '{}',
  item_count int  not null check (item_count > 0),
  sort_order int  not null
);

create table if not exists public.grammar_progress (
  user_id         uuid not null references auth.users (id) on delete cascade,
  skill_id        int  not null references public.grammar_skills (id) on delete cascade,
  status          text not null default 'learning' check (status in ('learning','familiar','strong')),
  studied_at      timestamptz not null default now(),
  streak          int  not null default 0 check (streak >= 0),
  stability       double precision check (stability > 0),
  fsrs_difficulty double precision check (fsrs_difficulty between 1 and 10),
  last_review_at  timestamptz,
  next_review_at  timestamptz not null,
  times_correct   int  not null default 0 check (times_correct >= 0),
  times_incorrect int  not null default 0 check (times_incorrect >= 0),
  updated_at      timestamptz not null default now(),
  primary key (user_id, skill_id)
);

drop trigger if exists grammar_progress_updated_at on public.grammar_progress;
create trigger grammar_progress_updated_at before update on public.grammar_progress
  for each row execute function public.set_updated_at();

create index if not exists grammar_progress_due_idx on public.grammar_progress (user_id, next_review_at);

create table if not exists public.daily_session_grammar (
  session_id uuid not null references public.daily_sessions (id) on delete cascade,
  skill_id   int  not null references public.grammar_skills (id) on delete cascade,
  position   int  not null,
  primary key (session_id, skill_id)
);

create table if not exists public.grammar_answers (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  daily_session_id uuid not null references public.daily_sessions (id) on delete cascade,
  skill_id         int  not null references public.grammar_skills (id) on delete cascade,
  item_id          text not null check (item_id ~ '^[0-9]{4}:[0-9]{1,3}$'),
  user_answer      text not null,
  correct_answer   text not null,
  is_correct       boolean not null,
  error_category   text not null check (error_category in ('case','gender','verb_form','word_order','adjective_ending','preposition','pronoun','negation','tense','mood','other')),
  created_at       timestamptz not null default now()
);

create index if not exists grammar_answers_user_idx on public.grammar_answers (user_id, created_at);

alter table public.daily_sessions add column if not exists grammar_completed_at timestamptz;

alter table public.grammar_skills        enable row level security;
alter table public.grammar_progress      enable row level security;
alter table public.daily_session_grammar enable row level security;
alter table public.grammar_answers       enable row level security;

revoke all on public.grammar_skills, public.grammar_progress, public.daily_session_grammar, public.grammar_answers
  from anon, authenticated;
grant select on public.grammar_skills, public.grammar_progress, public.daily_session_grammar, public.grammar_answers
  to authenticated;

drop policy if exists "grammar skills readable by signed-in users" on public.grammar_skills;
create policy "grammar skills readable by signed-in users" on public.grammar_skills
  for select to authenticated using (true);
drop policy if exists "own grammar progress: read" on public.grammar_progress;
create policy "own grammar progress: read" on public.grammar_progress
  for select to authenticated using (user_id = auth.uid());
drop policy if exists "own session grammar: read" on public.daily_session_grammar;
create policy "own session grammar: read" on public.daily_session_grammar
  for select to authenticated using (
    exists (select 1 from public.daily_sessions s where s.id = session_id and s.user_id = auth.uid()));
drop policy if exists "own grammar answers: read" on public.grammar_answers;
create policy "own grammar answers: read" on public.grammar_answers
  for select to authenticated using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- record_grammar_study: called after the learner practised skills on a lesson page.
-- Studied skills join the review schedule from tomorrow (local midnight). Practising a skill that is
-- already studied changes nothing, so the schedule cannot be reset by accident.
-- ---------------------------------------------------------------------------
create or replace function public.record_grammar_study(p_skill_ids int[])
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_profile public.profiles;
  v_count   int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_skill_ids is null or cardinality(p_skill_ids) = 0 or cardinality(p_skill_ids) > 20 then
    raise exception 'invalid skills';
  end if;
  if exists (select 1 from unnest(p_skill_ids) x(id) where not exists (select 1 from grammar_skills s where s.id = x.id)) then
    raise exception 'unknown skill';
  end if;
  select * into v_profile from profiles where id = v_uid;

  select v_uid, x.id, (((now() at time zone v_profile.timezone)::date + 1)::timestamp at time zone v_profile.timezone)
    from (select distinct unnest(p_skill_ids) as id) x
  on conflict (user_id, skill_id) do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- submit_grammar_review: stores the day's grammar answers and the new schedule of each skill
-- (computed by the browser with FSRS, validated here), once per session.
-- p_entries: [{skill_id, item_id, user_answer, correct_answer, is_correct, error_category,
--              status, streak, stability, fsrs_difficulty, next_review_at}]
-- ---------------------------------------------------------------------------
create or replace function public.submit_grammar_review(p_session_id uuid, p_entries jsonb)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_now     timestamptz := now();
  v_session public.daily_sessions;
  v_expect  int;
  v_score   int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  select * into v_session from daily_sessions where id = p_session_id and user_id = v_uid for update;
  if not found then
    raise exception 'session not found';
  end if;
  if v_session.grammar_completed_at is not null then
    raise exception 'grammar already submitted';
  end if;
  if jsonb_typeof(p_entries) is distinct from 'array' then
    raise exception 'entries must be an array';
  end if;

  select count(*) into v_expect from daily_session_grammar where session_id = p_session_id;
  if (select count(*) from jsonb_to_recordset(p_entries) e(skill_id int)) <> v_expect
     or (select count(distinct e.skill_id) from jsonb_to_recordset(p_entries) e(skill_id int)) <> v_expect
     or exists (select 1 from jsonb_to_recordset(p_entries) e(skill_id int)
                 where not exists (select 1 from daily_session_grammar sg
                                    where sg.session_id = p_session_id and sg.skill_id = e.skill_id)) then
    raise exception 'entries must cover each grammar skill of the session exactly once';
  end if;

  if exists (
    select 1
      from jsonb_to_recordset(p_entries)
           e(skill_id int, item_id text, user_answer text, correct_answer text, is_correct boolean,
             error_category text, status text, streak int, stability double precision,
             fsrs_difficulty double precision, next_review_at timestamptz)
      left join grammar_skills s on s.id = e.skill_id
     where e.item_id is null or e.item_id !~ '^[0-9]{4}:[0-9]{1,3}$'
        or split_part(e.item_id, ':', 1) <> e.skill_id::text
        or split_part(e.item_id, ':', 2)::int not between 1 and s.item_count
        or e.user_answer is null or length(e.user_answer) > 200
        or e.correct_answer is null or length(e.correct_answer) > 300
        or e.is_correct is null
        or e.error_category is null or e.error_category not in ('case','gender','verb_form','word_order','adjective_ending','preposition','pronoun','negation','tense','mood','other')
        or e.status is null or e.status not in ('learning','familiar','strong')
        or e.streak is null or e.streak < 0
        or e.stability is null or e.stability < 0.001 or e.stability > 36500
        or e.fsrs_difficulty is null or e.fsrs_difficulty < 1 or e.fsrs_difficulty > 10
        or e.next_review_at is null or e.next_review_at <= v_now or e.next_review_at > v_now + interval '1830 days') then
    raise exception 'invalid grammar entries';
  end if;

  select v_uid, p_session_id, e.skill_id, e.item_id, e.user_answer, e.correct_answer, e.is_correct, e.error_category
    from jsonb_to_recordset(p_entries)
         e(skill_id int, item_id text, user_answer text, correct_answer text, is_correct boolean, error_category text);

  update grammar_progress gp
     set status          = e.status,
         streak          = e.streak,
         stability       = e.stability,
         fsrs_difficulty = e.fsrs_difficulty,
         last_review_at  = v_now,
         next_review_at  = e.next_review_at,
         times_correct   = gp.times_correct + case when e.is_correct then 1 else 0 end,
         times_incorrect = gp.times_incorrect + case when e.is_correct then 0 else 1 end
    from jsonb_to_recordset(p_entries)
         e(skill_id int, is_correct boolean, status text, streak int, stability double precision,
           fsrs_difficulty double precision, next_review_at timestamptz)
   where gp.user_id = v_uid and gp.skill_id = e.skill_id;

  update daily_sessions set grammar_completed_at = v_now where id = p_session_id;

  select count(*) filter (where e.is_correct) into v_score
    from jsonb_to_recordset(p_entries) e(is_correct boolean);
  return v_score;
end;
$$;

create or replace function public.create_daily_session_for(p_user_id uuid, p_session_date date)
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_profile    public.profiles;
  v_session    public.daily_sessions;
  v_target     int;
  v_min_new    int;
  v_day_start  timestamptz;
  v_day_end    timestamptz;
  v_user_rank  int;
  v_new_avail  int;
  v_due_count  int;
  v_review_cap int;
  v_due        int[];
  v_struggling int[];
  v_reviews    int[];
  v_new        int[];
  v_fill       int[];
begin
  select * into v_session from daily_sessions
   where user_id = p_user_id and session_date = p_session_date;
  if found then
    return v_session;
  end if;

  select * into v_profile from profiles where id = p_user_id;
  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  v_target    := v_profile.daily_word_target;
  v_day_start := p_session_date::timestamp at time zone v_profile.timezone;
  v_day_end   := (p_session_date + 1)::timestamp at time zone v_profile.timezone;
  v_user_rank := cefr_rank(v_profile.current_cefr_level);

  -- How many new words to keep, depending on the review backlog:
  --   up to the target due      -> at least 20% new (10 -> 2)
  --   1x..2x the target due     -> at least 10% new (10 -> 1)
  --   2x the target or more due -> catch-up day, no new words until the backlog shrinks
  -- Forcing new words in while reviews pile up makes the backlog grow without limit.
  select count(*) into v_due_count
    from vocabulary_progress p
   where p.user_id = p_user_id and p.next_review_at < v_day_end;
  v_min_new := case
                 when v_due_count <= v_target    then ceil(v_target * 0.2)::int
                 when v_due_count < 2 * v_target then ceil(v_target * 0.1)::int
                 else 0
               end;

  select count(*) into v_new_avail
    from vocabulary_words w
   where not exists (select 1 from vocabulary_progress p
                      where p.user_id = p_user_id and p.word_id = w.id);

  v_review_cap := v_target - least(v_min_new, v_new_avail);

  -- 1. Words due for review by the end of the learner's local day.
  --    Frequently-wrong words first, then the ones most likely forgotten (lowest predicted recall).
  v_due := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at < v_day_end
     order by (p.times_incorrect > p.times_correct) desc,
              fsrs_retrievability(p.stability, coalesce(p.last_review_at, p.last_seen_at), v_day_start),
              p.next_review_at, p.word_id
     limit v_review_cap);

  -- 2. Up to two frequently-wrong words that are not due yet (not seen today).
  v_struggling := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at >= v_day_end
       and p.times_incorrect >= 2
       and p.times_incorrect >= p.times_correct
       and p.last_seen_at < v_day_start
     order by p.times_incorrect - p.times_correct desc, p.difficulty desc, p.word_id
     limit least(2, v_review_cap - cardinality(v_due)));

  v_reviews := v_due || v_struggling;

  -- 3. New words: learner's level first, then lower levels, then higher ones.
  --    Within a level, interleave topics (topic_rank) by frequency for variety.
  v_new := array(
    select c.id
      from (
        select w.id,
               w.frequency_rank,
               case
                 when cefr_rank(w.cefr_level) = v_user_rank then 0
                 when cefr_rank(w.cefr_level) < v_user_rank then v_user_rank - cefr_rank(w.cefr_level)
                 else 3 + cefr_rank(w.cefr_level) - v_user_rank
               end as level_priority,
               w.topic
          from vocabulary_words w
         where not exists (select 1 from vocabulary_progress p
                            where p.user_id = p_user_id and p.word_id = w.id)
      ) c
     order by c.level_priority,
              row_number() over (partition by c.level_priority, c.topic order by c.frequency_rank, c.id),
              c.frequency_rank,
              c.id
     limit v_target - cardinality(v_reviews));

  -- 4. Out of new words: top up with the earliest upcoming reviews.
  if cardinality(v_reviews) + cardinality(v_new) < v_target then
    v_fill := array(
      select p.word_id
        from vocabulary_progress p
       where p.user_id = p_user_id
         and p.word_id <> all (v_reviews)
       order by p.next_review_at nulls first, p.word_id
       limit v_target - cardinality(v_reviews) - cardinality(v_new));
    v_reviews := v_reviews || v_fill;
  end if;

  values (p_user_id, p_session_date, cardinality(v_new), cardinality(v_reviews),
          cardinality(v_new) + cardinality(v_reviews))
  on conflict (user_id, session_date) do nothing
  returning * into v_session;

  if not found then
    -- a concurrent call created it first
    select * into v_session from daily_sessions
     where user_id = p_user_id and session_date = p_session_date;
    return v_session;
  end if;

  select v_session.id, x.word_id, x.ord::int, 'new'
    from unnest(v_new) with ordinality as x(word_id, ord);

  select v_session.id, x.word_id, cardinality(v_new) + x.ord::int, 'review'
    from unnest(v_reviews) with ordinality as x(word_id, ord);

  update vocabulary_progress
     set status = 'review'
   where user_id = p_user_id and word_id = any (v_reviews);

  -- 5. Grammar: up to 3 studied skills that are due, the one most likely forgotten first.
  --    Mixed practice: one skill per lesson topic before a second skill from the same topic.
  select v_session.id, g.skill_id, row_number() over (order by g.second_of_topic, g.recall, g.skill_id)
    from (
      select gp.skill_id,
             fsrs_retrievability(gp.stability, gp.last_review_at, v_day_start) as recall,
             row_number() over (partition by gs.topic_id
                                order by fsrs_retrievability(gp.stability, gp.last_review_at, v_day_start), gp.skill_id) > 1
               as second_of_topic
        from grammar_progress gp
        join grammar_skills gs on gs.id = gp.skill_id
       where gp.user_id = p_user_id
         and gp.next_review_at < v_day_end
    ) g
   order by g.second_of_topic, g.recall, g.skill_id
   limit 3;

  return v_session;
end;
$$;

create or replace function public.save_session_progress(
  p_session_id     uuid,
  p_study_position int  default null,
  p_question_id    text default null,
  p_answer         text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_uid     uuid := auth.uid();
  v_session public.daily_sessions;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  select * into v_session from daily_sessions
   where id = p_session_id and user_id = v_uid
   for update;
  if not found then
    raise exception 'session not found';
  end if;
  if v_session.status = 'completed' then
    raise exception 'session already completed';
  end if;

  if p_question_id is not null then
    -- question ids: "<wordId>:<type>" (vocabulary) or "g<skillId>:<n>" (grammar); both must belong to this session
    if p_answer is null or length(p_answer) > 200
       or not (case
                 when p_question_id ~ '^[0-9]{1,9}:[a-z_]{1,20}$' then
                   exists (select 1 from daily_session_words sw
                            where sw.session_id = p_session_id
                              and sw.word_id = split_part(p_question_id, ':', 1)::int)
                 when p_question_id ~ '^g[0-9]{4}:[0-9]{1,3}$' then
                   exists (select 1 from daily_session_grammar sg
                            where sg.session_id = p_session_id
                              and sg.skill_id = substr(split_part(p_question_id, ':', 1), 2)::int)
                 else false
               end) then
      raise exception 'invalid answer';
    end if;
  end if;

  update daily_sessions s
     set study_position = case
           when p_study_position is null then s.study_position
           else greatest(s.study_position, least(p_study_position, s.total_word_count))
         end,
         quiz_draft = case
           when p_question_id is null then s.quiz_draft
           else jsonb_build_object(
                  'startedAt', coalesce(s.quiz_draft -> 'startedAt', to_jsonb(now())),
                  -- right side wins in ||, so an answer that is already saved is kept
                  'answers', jsonb_build_object(p_question_id, p_answer)
                             || coalesce(s.quiz_draft -> 'answers', '{}'::jsonb))
         end
   where s.id = p_session_id;
end;
$$;

revoke execute on function public.create_daily_session_for(uuid, date) from public, anon, authenticated;
revoke execute on function public.record_grammar_study(int[]) from public, anon;
revoke execute on function public.submit_grammar_review(uuid, jsonb) from public, anon;
revoke execute on function public.save_session_progress(uuid, int, text, text) from public, anon;
grant  execute on function public.record_grammar_study(int[]) to authenticated;
grant  execute on function public.submit_grammar_review(uuid, jsonb) to authenticated;
grant  execute on function public.save_session_progress(uuid, int, text, text) to authenticated;

-- make the API see the new tables and functions immediately
notify pgrst, 'reload schema';

-- ===== supabase/migrations/20261017000008_email_reminders.sql =====
-- Daily email reminders.
-- 1. profiles get email_reminders (on by default, the learner can switch it off), reminder_hour (local
--    hour 0..23 from which the reminder may go out, default 18) and last_reminder_date (local date of
--    the last reminder, so at most one per day).
-- 2. claim_due_reminders(p_now) picks everyone who should get a reminder now and marks them as
--    reminded for their local date. It has no side effects outside the database, so it is testable;
--    the actual sending (pg_net -> Resend) and its hourly schedule live in 0009_reminder_cron.
-- 3. Every reminder carries a one-click unsubscribe link with the profile's reminder_token, handled by
--    unsubscribe_reminders(token), which works signed out (anon).
-- Who gets one: onboarded, reminders on, has an email, local time >= reminder_hour, not reminded today,
-- today's lesson not completed yet, and active in the last 14 days (completed a lesson or onboarded),
-- so people who stopped using the app aren't emailed forever.

alter table public.profiles
  add column if not exists email_reminders    boolean not null default true,
  add column if not exists reminder_hour      int     not null default 18 check (reminder_hour between 0 and 23),
  add column if not exists last_reminder_date date,
  add column if not exists reminder_token     uuid    not null default gen_random_uuid();

create unique index if not exists profiles_reminder_token_idx on public.profiles (reminder_token);

grant update (email_reminders, reminder_hour) on public.profiles to authenticated;

create or replace function public.claim_due_reminders(
  p_now          timestamptz default now(),
  p_inactive_days int default 14)
returns table (user_id uuid, email text, local_date date, word_count int, grammar_count int, reminder_token uuid)
language plpgsql security definer set search_path = public as $$
begin
  return query
  with due as (
    select p.id, u.email::text as email, (p_now at time zone p.timezone)::date as d, p.daily_word_target, p.reminder_token as token
      from profiles p
      join auth.users u on u.id = p.id
     where p.onboarded_at is not null
       and p.email_reminders
       and coalesce(u.email, '') <> ''
       and extract(hour from p_now at time zone p.timezone) >= p.reminder_hour
       and p.last_reminder_date is distinct from (p_now at time zone p.timezone)::date
       and not exists (select 1 from daily_sessions s
                        where s.user_id = p.id and s.session_date = (p_now at time zone p.timezone)::date
                          and s.status = 'completed')
       and greatest(p.onboarded_at,
                    (select max(s.completed_at) from daily_sessions s where s.user_id = p.id))
           >= p_now - make_interval(days => p_inactive_days)
     for update of p skip locked
  ),
  claimed as (
    update profiles p set last_reminder_date = due.d
      from due where p.id = due.id
    returning p.id
  )
  select due.id, due.email, due.d,
         coalesce(s.total_word_count, due.daily_word_target),
         coalesce((select count(*)::int from daily_session_grammar g where g.session_id = s.id), 0),
         due.token
    from due
    join claimed c on c.id = due.id
    left join daily_sessions s on s.user_id = due.id and s.session_date = due.d
   order by due.id;
end;
$$;

-- One-click unsubscribe from the link in the email; the token is the only credential.
create or replace function public.unsubscribe_reminders(p_token uuid)
returns boolean
language sql security definer set search_path = public as $$
  with u as (update profiles set email_reminders = false where reminder_token = p_token returning 1)
  select exists (select 1 from u)
$$;

revoke execute on function public.claim_due_reminders(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.unsubscribe_reminders(uuid) from public;
grant  execute on function public.unsubscribe_reminders(uuid) to anon, authenticated;

-- make the API see the new columns and functions immediately
notify pgrst, 'reload schema';

-- ===== supabase/migrations/20261017000009_reminder_cron.sql =====
-- Sends the daily reminder emails (picked by claim_due_reminders, 0008) through Resend's HTTP API,
-- using pg_net, scheduled hourly by pg_cron. Everything stays inside Supabase: no Edge Function.
--
-- One-time setup (SQL Editor), with an API key from resend.com and a sender on a domain verified there:
--   select vault.create_secret('re_...', 'resend_api_key');
--   select vault.create_secret('Lernbrot <reminders@your-domain.com>', 'reminder_from');
-- Without these secrets the job does nothing (and marks nobody as reminded).
--
-- pg_net is asynchronous: a learner is marked as reminded when the request is queued, so a failed send
-- is not retried that day (at most one email per day). Check results with:
--   select r.*, h.status_code, h.content from public.reminder_emails r
--     left join net._http_response h on h.id = r.request_id order by r.created_at desc limit 20;
-- (pg_net keeps responses for about 6 hours.)

create extension if not exists pg_net;

create table if not exists public.reminder_emails (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references auth.users (id) on delete cascade,
  local_date date not null,
  request_id bigint,
  created_at timestamptz not null default now()
);
-- RLS on, no policies -> invisible to anon/authenticated.
alter table public.reminder_emails enable row level security;
revoke all on public.reminder_emails from anon, authenticated;

create or replace function public.send_daily_reminders(p_now timestamptz default now())
returns int
language plpgsql security definer set search_path = public as $$
declare
  c_app_url constant text := 'https://kamil-curzytek.github.io/lernbrot/';
  v_key     text;
  v_from    text;
  r         record;
  v_unsub   text;
  v_what    text;
  v_html    text;
  v_text    text;
  v_req     bigint;
  v_sent    int := 0;
begin
  select decrypted_secret into v_key  from vault.decrypted_secrets where name = 'resend_api_key';
  select decrypted_secret into v_from from vault.decrypted_secrets where name = 'reminder_from';
  if coalesce(v_key, '') = '' or coalesce(v_from, '') = '' then
    raise notice 'daily reminders: vault secrets resend_api_key / reminder_from are not set';
    return 0;
  end if;

  for r in select * from claim_due_reminders(p_now) loop
    v_unsub := c_app_url || '#/unsubscribe/' || r.reminder_token;
    v_what := r.word_count || case when r.word_count = 1 then ' word' else ' words' end
      || case when r.grammar_count > 0
              then ' and ' || r.grammar_count || ' grammar ' || case when r.grammar_count = 1 then 'exercise' else 'exercises' end
              else '' end;
    v_text := format(E'Hallo!\n\nYour German lesson for today is waiting: %s.\nIt only takes a few minutes.\n\nStart now: %s\n\n--\nDon''t want these reminders? Turn them off: %s\n',
                     v_what, c_app_url, v_unsub);
    v_html := format(
      '<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:480px;margin:0 auto;padding:24px;color:#222">'
      || '<h1 style="font-size:22px;margin:0 0 12px">Hallo! 👋</h1>'
      || '<p style="font-size:16px;line-height:1.5;margin:0 0 20px">Your German lesson for today is waiting: <strong>%s</strong>. It only takes a few minutes.</p>'
      || '<p style="margin:0 0 28px"><a href="%s" style="display:inline-block;background:#2f6f4f;color:#fff;text-decoration:none;padding:12px 20px;border-radius:8px;font-weight:600">Start today''s lesson</a></p>'
      || '<p style="font-size:12px;color:#888;margin:0">You get this because daily reminders are on in Lernbrot. '
      || '<a href="%s" style="color:#888">Turn off reminders</a> or change the time under Progress → Settings.</p>'
      || '</div>',
      v_what, c_app_url, v_unsub);

    begin
      select net.http_post(
        url     := 'https://api.resend.com/emails',
        headers := jsonb_build_object('Authorization', 'Bearer ' || v_key, 'Content-Type', 'application/json'),
        body    := jsonb_build_object(
          'from', v_from,
          'to', jsonb_build_array(r.email),
          'subject', 'Your German lesson is ready (' || v_what || ')',
          'html', v_html,
          'text', v_text,
          'headers', jsonb_build_object('List-Unsubscribe', '<' || v_unsub || '>'))
      ) into v_req;
      v_sent := v_sent + 1;
    exception when others then
      -- one bad address must not stop everyone else's reminder
      raise warning 'reminder for % failed: %', r.user_id, sqlerrm;
    end;
  end loop;
  return v_sent;
end;
$$;

revoke execute on function public.send_daily_reminders(timestamptz) from public, anon, authenticated;

-- Minute 20 of every hour (after the daily job at :05 has prepared sessions). The local-hour gate in
-- claim_due_reminders makes hourly runs serve every timezone. Same job name = replaced (safe to re-run).
select cron.schedule(
  'lernbrot-daily-reminders',
  '20 * * * *',
  $$select public.send_daily_reminders()$$
);

-- ===== supabase/migrations/20261026000010_push_reminders.sql =====
-- Daily reminders as push notifications (Web Push), next to the reminder emails of 0008.
-- 1. push_subscriptions: one row per device that allowed notifications. Learners read their own rows;
--    writes go through save_push_subscription / delete_push_subscription.
-- 2. due_reminder_profiles(p_now) holds the "who should be reminded now" rule shared by both channels:
--    onboarded, local time >= reminder_hour, today's lesson not completed, active in the last N days.
--    claim_due_reminders (email, same signature as before) now uses it too.
-- 3. claim_due_push_reminders(p_now) returns every device of each due learner and marks the learner as
--    pushed for their local date (profiles.last_push_date), so at most one push per day. It is called
--    by the send-push-reminders Edge Function (service_role), which is triggered hourly (0011).
-- Push and email are independent: a learner can have either, both or neither.

alter table public.profiles add column if not exists last_push_date date;

create table if not exists public.push_subscriptions (
  id           bigint generated always as identity primary key,
  user_id      uuid not null references auth.users (id) on delete cascade,
  endpoint     text not null unique check (endpoint ~ '^https://' and length(endpoint) <= 1000),
  -- base64url without padding: 65-byte P-256 public key, 16-byte auth secret
  p256dh       text not null check (p256dh ~ '^[A-Za-z0-9_-]{87}$'),
  auth_secret  text not null check (auth_secret ~ '^[A-Za-z0-9_-]{22}$'),
  created_at   timestamptz not null default now(),
  last_sent_at timestamptz
);

create index if not exists push_subscriptions_user_idx on public.push_subscriptions (user_id);

alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon, authenticated;
grant select on public.push_subscriptions to authenticated;
-- the Edge Function records deliveries and removes subscriptions the push service reports as gone
grant select, update (last_sent_at), delete on public.push_subscriptions to service_role;

drop policy if exists "own push subscriptions: read" on public.push_subscriptions;
create policy "own push subscriptions: read" on public.push_subscriptions
  for select to authenticated using (user_id = auth.uid());

-- Called by the browser after the learner allowed notifications. The same device signing in with another
-- account takes its subscription along. At most 10 devices per learner (the oldest are dropped).
create or replace function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  values (auth.uid(), p_endpoint, p_p256dh, p_auth)
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth_secret = excluded.auth_secret, created_at = now();
  delete from push_subscriptions
   where user_id = auth.uid()
     and id not in (select id from push_subscriptions where user_id = auth.uid() order by created_at desc, id desc limit 10);
end;
$$;

create or replace function public.delete_push_subscription(p_endpoint text)
returns void
language sql security definer set search_path = public as $$
  delete from push_subscriptions where endpoint = p_endpoint and user_id = auth.uid()
$$;

create or replace function public.due_reminder_profiles(p_now timestamptz, p_inactive_days int)
returns table (user_id uuid, local_date date, word_count int, grammar_count int)
language sql stable security definer set search_path = public as $$
  select p.id, d.local_date,
         coalesce(s.total_word_count, p.daily_word_target),
         coalesce((select count(*)::int from daily_session_grammar g where g.session_id = s.id), 0)
    from profiles p
    cross join lateral (select (p_now at time zone p.timezone)::date as local_date) d
    left join daily_sessions s on s.user_id = p.id and s.session_date = d.local_date
   where p.onboarded_at is not null
     and extract(hour from p_now at time zone p.timezone) >= p.reminder_hour
     and s.status is distinct from 'completed'
     and greatest(p.onboarded_at, (select max(c.completed_at) from daily_sessions c where c.user_id = p.id))
         >= p_now - make_interval(days => p_inactive_days)
$$;

-- Email channel (0008), now on the shared rule. The update's WHERE re-checks last_reminder_date under the
-- row lock, so overlapping runs can't remind anyone twice.
create or replace function public.claim_due_reminders(
  p_now          timestamptz default now(),
  p_inactive_days int default 14)
returns table (user_id uuid, email text, local_date date, word_count int, grammar_count int, reminder_token uuid)
language plpgsql security definer set search_path = public as $$
begin
  return query
  with claimed as (
    update profiles p set last_reminder_date = d.local_date
      from due_reminder_profiles(p_now, p_inactive_days) d, auth.users u
     where p.id = d.user_id and u.id = p.id
       and p.email_reminders
       and coalesce(u.email, '') <> ''
       and p.last_reminder_date is distinct from d.local_date
    returning p.id, u.email::text as email, d.local_date, d.word_count, d.grammar_count, p.reminder_token
  )
  select c.id, c.email, c.local_date, c.word_count, c.grammar_count, c.reminder_token from claimed c order by c.id;
end;
$$;

create or replace function public.claim_due_push_reminders(
  p_now          timestamptz default now(),
  p_inactive_days int default 14)
returns table (subscription_id bigint, endpoint text, p256dh text, auth_secret text, word_count int, grammar_count int)
language plpgsql security definer set search_path = public as $$
begin
  return query
  with claimed as (
    update profiles p set last_push_date = d.local_date
      from due_reminder_profiles(p_now, p_inactive_days) d
     where p.id = d.user_id
       and p.last_push_date is distinct from d.local_date
       and exists (select 1 from push_subscriptions ps where ps.user_id = p.id)
    returning p.id, d.word_count, d.grammar_count
  )
  select ps.id, ps.endpoint, ps.p256dh, ps.auth_secret, c.word_count, c.grammar_count
    from claimed c
    join push_subscriptions ps on ps.user_id = c.id
   order by ps.id;
end;
$$;

revoke execute on function public.due_reminder_profiles(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.claim_due_reminders(timestamptz, int) from public, anon, authenticated;
revoke execute on function public.claim_due_push_reminders(timestamptz, int) from public, anon, authenticated;
grant  execute on function public.claim_due_push_reminders(timestamptz, int) to service_role;
revoke execute on function public.save_push_subscription(text, text, text) from public, anon;
revoke execute on function public.delete_push_subscription(text) from public, anon;
grant  execute on function public.save_push_subscription(text, text, text) to authenticated;
grant  execute on function public.delete_push_subscription(text) to authenticated;

-- make the API see the new table and functions immediately
notify pgrst, 'reload schema';

-- ===== supabase/migrations/20261026000011_push_cron.sql =====
-- Triggers the send-push-reminders Edge Function every hour (minute :20) with pg_net. The function
-- claims who is due (claim_due_push_reminders, 0010) and sends the notifications.
--
-- One-time setup (SQL Editor): the function's URL and the same random secret you set as the
-- function's CRON_SECRET (see README, "Push notifications"):
--   select vault.create_secret('https://<project-ref>.supabase.co/functions/v1/send-push-reminders', 'push_function_url');
--   select vault.create_secret('<CRON_SECRET>', 'push_cron_secret');
-- Without these secrets the job does nothing. Check recent calls with:
--   select id, status_code, content, created from net._http_response order by created desc limit 5;

create extension if not exists pg_net;

create or replace function public.trigger_push_reminders()
returns bigint
language plpgsql security definer set search_path = public as $$
declare
  v_url    text;
  v_secret text;
begin
  select decrypted_secret into v_url    from vault.decrypted_secrets where name = 'push_function_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_cron_secret';
  if coalesce(v_url, '') = '' or coalesce(v_secret, '') = '' then
    raise notice 'push reminders: vault secrets push_function_url / push_cron_secret are not set';
    return null;
  end if;
  return net.http_post(
    url     := v_url,
    body    := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secret),
    timeout_milliseconds := 60000
  );
end;
$$;

revoke execute on function public.trigger_push_reminders() from public, anon, authenticated;

-- Same job name = replaced (safe to re-run).
select cron.schedule(
  'lernbrot-push-reminders',
  '20 * * * *',
  $$select public.trigger_push_reminders()$$
);

-- ===== supabase/migrations/20261029000012_new_words_every_day.sql =====
-- New words every day: the catch-up tier (2x the target or more due) used to drop new words to zero.
-- It now keeps the busy-day minimum of 10% (at least one word), so every lesson has something new.
-- create_daily_session_for is otherwise unchanged from 0007.

create or replace function public.create_daily_session_for(p_user_id uuid, p_session_date date)
returns public.daily_sessions
language plpgsql security definer set search_path = public as $$
declare
  v_profile    public.profiles;
  v_session    public.daily_sessions;
  v_target     int;
  v_min_new    int;
  v_day_start  timestamptz;
  v_day_end    timestamptz;
  v_user_rank  int;
  v_new_avail  int;
  v_due_count  int;
  v_review_cap int;
  v_due        int[];
  v_struggling int[];
  v_reviews    int[];
  v_new        int[];
  v_fill       int[];
begin
  select * into v_session from daily_sessions
   where user_id = p_user_id and session_date = p_session_date;
  if found then
    return v_session;
  end if;

  select * into v_profile from profiles where id = p_user_id;
  if not found then
    raise exception 'profile % not found', p_user_id;
  end if;

  v_target    := v_profile.daily_word_target;
  v_day_start := p_session_date::timestamp at time zone v_profile.timezone;
  v_day_end   := (p_session_date + 1)::timestamp at time zone v_profile.timezone;
  v_user_rank := cefr_rank(v_profile.current_cefr_level);

  -- How many new words to keep, depending on the review backlog:
  --   up to the target due      -> at least 20% new (10 -> 2)
  --   more than the target due  -> at least 10% new (10 -> 1), so there is something new every day
  select count(*) into v_due_count
    from vocabulary_progress p
   where p.user_id = p_user_id and p.next_review_at < v_day_end;
  v_min_new := case
                 when v_due_count <= v_target then ceil(v_target * 0.2)::int
                 else ceil(v_target * 0.1)::int
               end;

  select count(*) into v_new_avail
    from vocabulary_words w
   where not exists (select 1 from vocabulary_progress p
                      where p.user_id = p_user_id and p.word_id = w.id);

  v_review_cap := v_target - least(v_min_new, v_new_avail);

  -- 1. Words due for review by the end of the learner's local day.
  --    Frequently-wrong words first, then the ones most likely forgotten (lowest predicted recall).
  v_due := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at < v_day_end
     order by (p.times_incorrect > p.times_correct) desc,
              fsrs_retrievability(p.stability, coalesce(p.last_review_at, p.last_seen_at), v_day_start),
              p.next_review_at, p.word_id
     limit v_review_cap);

  -- 2. Up to two frequently-wrong words that are not due yet (not seen today).
  v_struggling := array(
    select p.word_id
      from vocabulary_progress p
     where p.user_id = p_user_id
       and p.next_review_at >= v_day_end
       and p.times_incorrect >= 2
       and p.times_incorrect >= p.times_correct
       and p.last_seen_at < v_day_start
     order by p.times_incorrect - p.times_correct desc, p.difficulty desc, p.word_id
     limit least(2, v_review_cap - cardinality(v_due)));

  v_reviews := v_due || v_struggling;

  -- 3. New words: learner's level first, then lower levels, then higher ones.
  --    Within a level, interleave topics (topic_rank) by frequency for variety.
  v_new := array(
    select c.id
      from (
        select w.id,
               w.frequency_rank,
               case
                 when cefr_rank(w.cefr_level) = v_user_rank then 0
                 when cefr_rank(w.cefr_level) < v_user_rank then v_user_rank - cefr_rank(w.cefr_level)
                 else 3 + cefr_rank(w.cefr_level) - v_user_rank
               end as level_priority,
               w.topic
          from vocabulary_words w
         where not exists (select 1 from vocabulary_progress p
                            where p.user_id = p_user_id and p.word_id = w.id)
      ) c
     order by c.level_priority,
              row_number() over (partition by c.level_priority, c.topic order by c.frequency_rank, c.id),
              c.frequency_rank,
              c.id
     limit v_target - cardinality(v_reviews));

  -- 4. Out of new words: top up with the earliest upcoming reviews.
  if cardinality(v_reviews) + cardinality(v_new) < v_target then
    v_fill := array(
      select p.word_id
        from vocabulary_progress p
       where p.user_id = p_user_id
         and p.word_id <> all (v_reviews)
       order by p.next_review_at nulls first, p.word_id
       limit v_target - cardinality(v_reviews) - cardinality(v_new));
    v_reviews := v_reviews || v_fill;
  end if;

  values (p_user_id, p_session_date, cardinality(v_new), cardinality(v_reviews),
          cardinality(v_new) + cardinality(v_reviews))
  on conflict (user_id, session_date) do nothing
  returning * into v_session;

  if not found then
    -- a concurrent call created it first
    select * into v_session from daily_sessions
     where user_id = p_user_id and session_date = p_session_date;
    return v_session;
  end if;

  select v_session.id, x.word_id, x.ord::int, 'new'
    from unnest(v_new) with ordinality as x(word_id, ord);

  select v_session.id, x.word_id, cardinality(v_new) + x.ord::int, 'review'
    from unnest(v_reviews) with ordinality as x(word_id, ord);

  update vocabulary_progress
     set status = 'review'
   where user_id = p_user_id and word_id = any (v_reviews);

  -- 5. Grammar: up to 3 studied skills that are due, the one most likely forgotten first.
  --    Mixed practice: one skill per lesson topic before a second skill from the same topic.
  select v_session.id, g.skill_id, row_number() over (order by g.second_of_topic, g.recall, g.skill_id)
    from (
      select gp.skill_id,
             fsrs_retrievability(gp.stability, gp.last_review_at, v_day_start) as recall,
             row_number() over (partition by gs.topic_id
                                order by fsrs_retrievability(gp.stability, gp.last_review_at, v_day_start), gp.skill_id) > 1
               as second_of_topic
        from grammar_progress gp
        join grammar_skills gs on gs.id = gp.skill_id
       where gp.user_id = p_user_id
         and gp.next_review_at < v_day_end
    ) g
   order by g.second_of_topic, g.recall, g.skill_id
   limit 3;

  return v_session;
end;
$$;

revoke execute on function public.create_daily_session_for(uuid, date) from public, anon, authenticated;

-- ===== supabase/seed/content.sql =====
-- GENERATED by scripts/build-seed.mjs from content/*.json. Do not edit by hand.
-- Idempotent: safe to run repeatedly.
begin;
on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  cefr_level = excluded.cefr_level,
  planned_order = excluded.planned_order,
  summary = excluded.summary,
  content = excluded.content;

on conflict (id) do update set
  topic_id = excluded.topic_id,
  slug = excluded.slug,
  title = excluded.title,
  category = excluded.category,
  requires = excluded.requires,
  item_count = excluded.item_count,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  german = excluded.german,
  english = excluded.english,
  part_of_speech = excluded.part_of_speech,
  article = excluded.article,
  plural = excluded.plural,
  cefr_level = excluded.cefr_level,
  frequency_rank = excluded.frequency_rank,
  topic = excluded.topic,
  example_sentence = excluded.example_sentence,
  example_translation = excluded.example_translation,
  usage_note = excluded.usage_note;

delete from public.vocabulary_grammar_links;
commit;
